window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Tryb przypuszczający (Konjunktiv II) i zdania z wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Na twoim miejscu …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"Rzeczywistość Evy – życzenia Evy. Uzupełnij: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Ale chciałaby być wyższa.","why":"*grösser sein*: forma życzenia od *sein* to **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Ale chciałaby dobrze mówić po hiszpańsku.","why":"Na końcu stoi bezokolicznik (*sprechen*), więc życzenie to **würde** + bezokolicznik.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Ale wolałaby pracować jako przewodniczka wycieczek.","why":"Bezokolicznik na końcu (*arbeiten*) → **würde** + bezokolicznik. *lieber* = raczej, chętniej.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Ale chciałaby mieć duże mieszkanie.","why":"*eine Wohnung haben*: forma życzenia od *haben* to **hätte**. Bezokolicznik nie jest potrzebny.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"Co myślą ci ludzie?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Dopasuj każdy obrazek do wyrażenia z ramki.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Gdybym nie musiał pracować, siedziałbym teraz w ogrodzie.","why":"Obrazek 1 pokazuje go przy pracy, a potem jak marzy na leżaku. Po zdaniu z *wenn* zdanie główne zaczyna się od czasownika (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Gdybym miał samochód, nie musiałbym jeździć na rowerze w deszczu.","why":"Jedzie na rowerze w deszczu; samochód by mu tego oszczędził. *müsste* to Konjunktiv II od *müssen*. *Velo* to szwajcarskie słowo na *Fahrrad* (rower).","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Gdyby autobus nie miał opóźnienia, byłabym punktualnie w biurze.","why":"Przez spóźniony autobus ona spóźnia się do pracy. *wäre* to Konjunktiv II od *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Przepisz zdania z a: zacznij od zdania głównego, potem zdanie z wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Nie musiałbym jeździć na rowerze w deszczu, gdybym miał samochód.","why":"Najpierw zdanie główne, potem zdanie z *wenn*. W zdaniu z *wenn* czasownik (*hätte*) idzie na koniec.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Byłabym punktualnie w biurze, gdyby autobus nie miał opóźnienia.","why":"Ten sam wzór: zdanie główne, przecinek, *wenn* … czasownik na końcu (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij słowami z ramki. Każde słowo jest użyte raz; przekreślone są użyte w przykładzie.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Zrobiłabym niektóre rzeczy inaczej, gdybym była szefową w naszej firmie.","why":"*machen* na końcu → **würde** + bezokolicznik. *Chefin sein* → **wäre**, na końcu zdania z *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Gdybym był Markiem, koniecznie zacząłbym naukę zawodu.","why":"*Marco sein* → **wäre** (jak w *Wenn ich du wäre …*). Zdanie główne ma bezokolicznik *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Gdybym mogła swobodnie decydować, pracowałabym w małej firmie.","why":"*frei entscheiden können* → **könnte** na końcu zdania z *wenn*. Zdanie główne z *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Gdybyśmy mieli dzieci, musiałabym pracować tylko na pół etatu.","why":"*Kinder haben* z *wir* → **hätten**. Ramka zostawia **müsste** na ostatnią lukę.","source":"k2","check":"W b, c i e zarówno *müsste*, jak i *würde* są poprawne po niemiecku (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* jest równie dobre). Ramka mówi tylko, które trzy luki dostają *würde*, a która *müsste*; ten klucz to najbardziej prawdopodobny podział. Zapytaj nauczyciela, którą wersję chce książka."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Muszę się spieszyć z powodu pracy.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Przepisz odpowiedzi, używając spójnika weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Bo moja dziewczyna jest niepunktualna.","why":"*wegen* + rzeczownik zamienia się w *weil* + zdanie z czasownikiem; czasownik (*ist*) idzie na koniec.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Bo pogoda jest zła.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; po *weil* czasownik idzie na koniec.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Bo mam ważne spotkanie.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (biernik po *haben*); czasownik na końcu.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Uzupełnij: wegen – weshalb – weil – deswegen – denn. Jednego słowa można użyć więcej niż raz.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"Słabo go rozumiem z powodu jego wymowy.","why":"Dalej stoi rzeczownik (*seiner Aussprache*, dopełniacz), a nie zdanie → przyimek **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Kiedyś chciałbym pojechać do Włoch, bo chciałbym zobaczyć morze.","why":"Po luce czasownik zostaje na drugim miejscu (*ich möchte*) → **denn**. Z *weil* poszedłby na koniec.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Muszę poprawić rozumienie ze słuchu, dlatego oglądam dużo filmów.","why":"Druga część to skutek, a czasownik stoi zaraz po luce (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"Moje dzieci szybko nauczyły się niemieckiego, bo w przedszkolu zawsze są razem ze szwajcarskimi dziećmi.","why":"Czasownik jest na końcu (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Dlaczego zapisujesz słowa na karteczkach?","why":"Potrzebny jest zaimek pytający: **Weshalb** znaczy *warum* (dlaczego)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Moja siostra mówi już prawie płynnie po niemiecku, dlatego może mi pomagać w nauce niemieckiego.","why":"Skutek, a czasownik stoi zaraz po luce (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Na kursie językowym. Uzupełnij: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Nie mogłem zrobić ostatniego ćwiczenia, bo go nie zrozumiałem.","why":"Czasownik jest na końcu (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"W rejestracji nikogo nie było. Dlatego wróciłem do domu.","why":"Nowe zdanie, które podaje skutek, z czasownikiem zaraz po luce (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Ze względu na dobre oceny nie musiałem pisać testu na początku kursu.","why":"Dalej stoi grupa rzeczownikowa (*meiner guten Noten*, dopełniacz liczby mnogiej) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"Jest dodatkowy kurs językowy, bo zapisało się bardzo wielu uczestników.","why":"Czasownik jest na końcu (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Wczoraj niestety nie mogłem przyjść na kurs z powodu bólu zębów.","why":"Dalej stoi grupa rzeczownikowa (*meiner Zahnschmerzen*, dopełniacz liczby mnogiej) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Kto znajdzie najlepsze wymówki? Wybierz jedną sytuację i napisz. Przykładowe odpowiedzi to tylko jedna z możliwości.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Niestety nie mogłem posprzątać kuchni, bo nagle bardzo rozbolały mnie plecy. Musiałem się położyć. Dlatego obejrzałem film.","why":"Używa *weil* (czasownik na końcu: *hatte*) i *Deswegen* (czasownik zaraz po nim: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"Z powodu grypy nie poszedłem na egzamin końcowy. Miałem wysoką gorączkę, dlatego zostałem w łóżku.","why":"Używa *wegen* + dopełniacz (*einer Grippe*) i *deswegen* + czasownik (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Bardzo mi przykro! Niestety się spóźniłem, bo na autostradzie był wypadek. Przez korek straciłem dwie godziny.","why":"*denn* zostawia czasownik na drugim miejscu (*war*). *wegen des Staus*: dopełniacz od *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (zdania warunkowe, także nierzeczywiste z Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"słownik spójników grammis: wenn (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"słownik spójników grammis: weil (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"słownik spójników grammis: denn (przyczynowy, czasownik zostaje na drugim miejscu)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"słownik spójników grammis: deswegen (skutek; stoi przed czasownikiem lub w środku zdania)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen z dopełniaczem)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Dorastanie z kilkoma językami · czytanie, wpis na forum, krzyżówka, ulubione słowa","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"Jak w domu w kilku językach","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Dwa lub trzy języki w jednej rodzinie – żaden problem?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Kto co mówi? Przeczytaj trzy teksty i przy każdym zdaniu napisz imię osoby, która je mówi.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"„Dzieci chcą mówić tym samym językiem co ich przyjaciele.” – Janusz","why":"Janusz (tekst B): *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"„Przecież to dobrze, kiedy ktoś bardzo dobrze mówi w kilku językach.” – Yara","why":"Yara (tekst C): *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"„Moje dzieci przeskakują między dwoma językami.” – Amira","why":"Amira (tekst A): *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* Tylko ona mówi o swoich własnych dzieciach."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Co jest prawdą? Przeczytaj teksty jeszcze raz. Po każdym zdaniu wpisz *richtig* (prawda) lub *falsch* (fałsz); w książce zaznaczasz tylko prawdziwe.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Dzieci Amiry mówią lepiej po arabsku niż po niemiecku. → prawda","why":"Rodzina zawsze mówi w domu po arabsku: *Darum können das die Kinder viel besser.* (Ich niemiecki to tutaj szwajcarski niemiecki.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"W rodzinie Amiry mówi się tylko po niemiecku. → fałsz","why":"Odwrotnie: *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz uczył się niemieckiego przez sześć lat. → fałsz","why":"Miał sześć lat, kiedy rodzina się przeprowadziła (*als ich sechs Jahre alt war*), a po roku mówił płynnie standardowym niemieckim (Hochdeutsch)."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz i jego siostra nie chcieli mówić z rodzicami po polsku. → prawda","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara mówi płynnie w trzech językach. → prawda","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* Niemiecki to jej czwarty język i jeszcze nie mówi nim dobrze."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara wkrótce zacznie też uczyć się niemieckiego. → fałsz","why":"Nie zaczyna wkrótce (*bald*): uczy się niemieckiego już od dwóch lat (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"Jak w domu w kilku językach","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Napisz wpis na forum. Po debacie telewizyjnej o dorastaniu z kilkoma językami znajdujesz na forum internetowym programu taką opinię:","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Zrób notatki do czterech pytań. Wystarczą krótkie notatki, bez pełnych zdań. Przykładowe notatki to jedna z możliwości.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Tak: syn mojej sąsiadki – włoski z mamą, szwajcarski niemiecki w szkole","why":"Tylko notatki: imię lub osoba i jakie języki gdzie."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"nauka dwóch języków bez kursu, kontakt z rodziną za granicą, korzyści w pracy","why":"Zbierz dwie lub trzy zalety; będą ci potrzebne do *Ich finde es sehr gut, dass …* w b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mieszanie języków, jeden język jest słabszy, dużo pracy dla rodziców","why":"To trafi do *Es könnte schwierig sein, dass …* i *Auf der anderen Seite …* w b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"nie – dzieci dobrze uczą się dwóch języków, jeśli rodzice dużo z nimi rozmawiają","why":"Zdecyduj, czy tak, czy nie, i podaj jeden powód – z tego powstanie *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Teraz napisz swoją opinię na ten temat (około 80 słów). Wykorzystaj swoje notatki z punktu a i kilka podanych zwrotów.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"Nie zgadzam się z Sandrą, bo wiele dzieci uczy się dwóch języków bez problemów. Syn mojej sąsiadki dorasta z włoskim i niemieckim. Z mamą mówi po włosku, a w szkole szwajcarskim niemieckim. Uważam, że to bardzo dobrze, że tak wcześnie uczy się dwóch języków. Trudne mogłoby być to, że czasem miesza języki. Z drugiej strony u małych dzieci to normalne. Najważniejsze ze wszystkiego jest to, żeby rodzice dużo rozmawiali z dzieckiem. Dlatego każde z rodziców powinno mówić swoim własnym językiem.","why":"Około 85 słów, z sześcioma zwrotami. *denn* zostawia czasownik na drugim miejscu (*lernen*); po *Deswegen* czasownik stoi zaraz potem (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Rozwiąż krzyżówkę. Każde zdanie podaje pierwszą literę brakującego słowa. Siatki tu nie ma: wpisz całe słowo. W siatce w książce Ä zajmuje jedną kratkę.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Naszą ojczyzną jest Hiszpania. Pochodzimy z Hiszpanii.","why":"*aus einem Land stammen* = pochodzić z jakiegoś kraju (jak *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda i Mike nie widzą się przez sześć miesięcy. To długa rozłąka.","why":"*die Trennung* = rozłąka, rozstanie, rzeczownik od *sich trennen*. *eine lange* → rzeczownik rodzaju żeńskiego."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"Niemiecki i arabski nie mają tego samego pisma.","why":"*die Schrift* = pismo, czyli litery, którymi zapisuje się język. Arabski używa innego alfabetu."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter mieszka teraz w Ameryce. Odkąd tam mieszka, bardzo się zmienił.","why":"*sich verändern* = zmieniać się (o człowieku). Perfekt: *hat sich verändert*. Ä zajmuje jedną kratkę."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Ona pisze książki. Z zawodu jest autorką.","why":"*Sie* → forma żeńska z *-in*: *der Autor → die Autorin*. Po *sein … von Beruf* nie ma rodzajnika."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"Dzieci nie odrabiają zadań domowych. Dlatego rodzice na nie krzyczą.","why":"*mit jemandem schimpfen* = besztać kogoś, krzyczeć na kogoś. Podmiot w liczbie mnogiej *die Eltern* → *schimpfen*. Po *Deshalb* czasownik stoi zaraz potem."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Pracuje dopiero od kilku miesięcy. Ma jeszcze niewielkie doświadczenie w zawodzie.","why":"*die Erfahrung* = doświadczenie. *wenig Erfahrung haben* = mieć niewielkie doświadczenie."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Teraz mamy chaos. Wszystko jest pomieszane.","why":"*durcheinander sein* = być w nieładzie, pomieszanym. Pisane łącznie."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Dla Ye-Jon głoski P i F brzmią tak samo. Nie potrafi ich rozróżnić.","why":"*unterscheiden* = rozróżniać. Z *kann* bezokolicznik idzie na koniec. *tönen* to szwajcarskie słowo na *klingen* (brzmieć)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"Na wakacje jadę do Grecji, ale niestety w ogóle nie mówię po grecku.","why":"*Griechisch* = język grecki, wielką literą. *kein Griechisch können* = w ogóle nie mówić po grecku."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"On je tylko warzywa i ryż. Je wyłącznie warzywa i ryż.","why":"*ausschliesslich* = wyłącznie, nic poza tym. Pisownia szwajcarska z *ss*; w Niemczech pisze się to z ostrym s (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Hasło (zaznaczony rząd w siatce): język ojczysty","why":"Każde słowo daje jedną literę zaznaczonego rzędu: stam**M**en, trenn**U**ng, schrif**T**, (T w siatce), veränd**E**rt, auto**R**in, (S w siatce), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"Jak w domu w kilku językach","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"Moje najpiękniejsze niemieckie słowo","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Dopasuj każde zdjęcie do słowa z ramki. Kolorowe kropki w książce podają rodzajnik: niebieska = der, zielona = das, czerwona = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (deser: krem z karmelem)","why":"Szwajcarska nazwa crème caramel. *Chöpfli* to w szwajcarskim niemieckim „główka” (*Kopf*). Zielona kropka → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – spadająca gwiazda","why":"*der Stern* = gwiazda; *die Sternschnuppe* = spadająca gwiazda. Czerwona kropka → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – motyl","why":"Szwajcarskie słowo na *der Schmetterling* (motyl); Duden oznacza je *schweizerisch, sonst landschaftlich*. Niebieska kropka → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Dlaczego ktoś może uważać właśnie te słowa za najpiękniejsze? Co o tym myślisz? Zrób notatki, potem o nich porozmawiajcie. Przykładowe notatki to jedna z możliwości.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"takie kolorowe i lekkie, przypomina lato, zabawne: to zwierzę wcale nie jest ptakiem","why":"Pomyśl, co to słowo każe ci zobaczyć lub poczuć i jak brzmi."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"słodkie, przypomina dzieciństwo, brzmi zabawnie i typowo szwajcarsko","why":"*tönen* to szwajcarskie słowo na *klingen* (brzmieć)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantyczne, można sobie czegoś życzyć, brzmi miękko","why":"Wystarczą krótkie notatki: przymiotniki i powód."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"Moje ulubione słowo","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Które niemieckie słowo i które słowo w twoim języku ojczystym lubisz? Dlaczego? Napisz krótki tekst, korzystając ze zwrotów. Przykładowa odpowiedź to jedna z możliwości.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"Moje ulubione niemieckie słowo to „gemütlich” (przytulny, swojski). Kiedy słyszę to słowo, myślę o zimowym wieczorze z herbatą, świecami i przyjaciółmi. Dlatego wydaje mi się takie ładne. Brzmi miękko i ciepło. W moim języku ojczystym, angielskim, nie ma słowa o dokładnie takim znaczeniu. Po angielsku podoba mi się słowo „sunshine”. Dla mnie to radosne słowo, bo brzmi jasno i przyjaźnie.","why":"*Wenn …, dann* + czasownik zaraz potem (*denke ich*); *Deshalb* + czasownik zaraz potem (*finde ich*). Wstaw własny język ojczysty i własne słowa.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Przedstaw swój tekst na zajęciach. Możliwy początek pokazuje przykład.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Chciałbym wam dziś przedstawić moje ulubione słowo. To słowo „gemütlich”. …","why":"Zacznij od podania słowa, potem przeczytaj swój tekst z a. *euch* do kolegów z grupy, *Ihnen*, jeśli mówisz oficjalnie."}]}]}],"sources":[{"id":"sommervogel","title":"Duden: Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"słownik spójników grammis: deswegen (skutek; stoi przed czasownikiem lub w środku zdania)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"słownik spójników grammis: wenn (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]},{"id":"03-nachfragen-test","no":3,"title":"Nachfragen · Fremdsprachen lernen · Test Lektion 4","title_en":"Grzeczne dopytywanie, nauka języków, szukanie pracy · test z lekcji 4","added":"2026-11-10","book":"Schritte plus Neu 5 · Arbeitsbuch und Testheft · Lektion 4","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (oficjalny klucz odpowiedzi, Lektion 4)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (zdania warunkowe, także nierzeczywiste z Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"weil","title":"słownik spójników grammis: weil (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"słownik spójników grammis: denn (przyczynowy, czasownik zostaje na drugim miejscu)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"słownik spójników grammis: deswegen (skutek; stoi przed czasownikiem lub w środku zdania)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"deshalb","title":"słownik spójników grammis: deshalb (skutek; synonimy daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"darum","title":"słownik spójników grammis: d(a)rum (skutek)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen z dopełniaczem)","url":"https://grammis.ids-mannheim.de/fragen/67"}],"pages":[{"page":"AB 133","heading":"C  Entschuldigung, könnten Sie das bitte wiederholen?","heading_en":"Przepraszam, czy mógłby Pan to powtórzyć?","exercises":[{"no":"13","tag":"C2","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij każde pytanie lub zdanie początkiem z ramki. Każdy początek jest użyty raz; przekreślony jest użyty w przykładzie.","box":["Tut mir leid, das Wort habe ich","Könnten Sie bitte langsamer","Entschuldigung, habe ich das","Könnten Sie das bitte","Darf ich Sie schnell","Was bedeutet","Könnten Sie mir vielleicht sagen","Wissen Sie, ob"],"box_used":[4],"box_exact":true,"example":[{"label":"a","text":"**Darf ich Sie schnell** etwas fragen?"}],"items":[{"label":"b","text":"___ der Ausdruck «es eilig haben»?","gaps":[["Was bedeutet"]],"solution":"**Was bedeutet** der Ausdruck «es eilig haben»?","en":"Co znaczy wyrażenie „es eilig haben”?","why":"*Was bedeutet …?* pyta o znaczenie słowa lub wyrażenia. (*es eilig haben* = spieszyć się.)","source":"hueber"},{"label":"c","text":"___ sprechen?","gaps":[["Könnten Sie bitte langsamer"]],"solution":"**Könnten Sie bitte langsamer** sprechen?","en":"Czy mógłby Pan mówić trochę wolniej?","why":"*Könnten Sie …* (Konjunktiv II) sprawia, że prośba jest grzeczna; bezokolicznik *sprechen* idzie na koniec.","source":"hueber"},{"label":"d","text":"___ nicht verstanden.","gaps":[["Tut mir leid, das Wort habe ich"]],"solution":"**Tut mir leid, das Wort habe ich** nicht verstanden.","en":"Przepraszam, nie zrozumiałem tego słowa.","why":"Perfekt: *habe … verstanden*; *das Wort* stoi na początku dla podkreślenia, więc czasownik *habe* stoi zaraz po nim.","source":"hueber"},{"label":"e","text":"Wie bitte? ___ wiederholen?","gaps":[["Könnten Sie das bitte"]],"solution":"Wie bitte? **Könnten Sie das bitte** wiederholen?","en":"Słucham? Czy mógłby Pan to powtórzyć?","why":"Grzeczna prośba z *Könnten Sie …*; *wiederholen* (powtórzyć) idzie na koniec.","source":"hueber"},{"label":"f","text":"___ es hier auch Integrationskurse gibt?","gaps":[["Wissen Sie, ob"]],"solution":"**Wissen Sie, ob** es hier auch Integrationskurse gibt?","en":"Czy wie Pani, czy są tu też kursy integracyjne?","why":"*ob* wprowadza zależne pytanie typu tak/nie, więc czasownik *gibt* idzie na koniec.","source":"hueber"},{"label":"g","text":"___ richtig verstanden?","gaps":[["Entschuldigung, habe ich das"]],"solution":"**Entschuldigung, habe ich das** richtig verstanden?","en":"Przepraszam, czy dobrze to zrozumiałem?","why":"Pytanie typu tak/nie w czasie Perfekt: *habe* na początku, *verstanden* na końcu.","source":"hueber"},{"label":"h","text":"___, wo die Mensa ist?","gaps":[["Könnten Sie mir vielleicht sagen"]],"solution":"**Könnten Sie mir vielleicht sagen**, wo die Mensa ist?","en":"Czy mogłaby mi Pani powiedzieć, gdzie jest stołówka?","why":"Pytanie zależne z *wo*: czasownik *ist* idzie na koniec. *die Mensa* = stołówka uczelniana.","source":"hueber"}]},{"no":"14","tag":"C2","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij dialogi. Wydrukowane pierwsze litery (i kilka liter w środku słów) są podane; wpisz całe brakujące słowa.","example":[{"label":"a","lead":"◆ Was ist denn das? ○ Das ist ein Zigerkrapfen. ◆ Entschuldigung, Zigerkrapfen kenne ich nicht.","text":"**Könnten Sie mir sagen**, was das ist?"}],"items":[{"label":"b","lead":"◆ Entschuldigen Sie bitte. Wo ist denn da die Mensa?  ○ Wie bitte? Das letzte Wort h… i… n… v… .  ◆ Die Mensa, die Uni-Kantine.","text":"Wie bitte? Das letzte Wort ___.","gaps":[["habe ich nicht verstanden"]],"solution":"Wie bitte? Das letzte Wort **habe ich nicht verstanden**.","en":"Słucham? Nie zrozumiałam ostatniego słowa.","why":"Perfekt: *habe* na drugim miejscu po *Das letzte Wort*, *verstanden* na końcu.","source":"hueber"},{"label":"c","lead":"◆ Also, dann treffen wir uns am 12.5. um 13.35 Uhr am Bahnhof.  ○ Entschuldigen Sie, es ist so laut da. K… S… den Termin b… w…?","text":"Entschuldigen Sie, es ist so laut da. ___ den Termin ___ ___?","gaps":[["Könnten Sie"],["bitte"],["wiederholen"]],"solution":"Entschuldigen Sie, es ist so laut da. **Könnten Sie** den Termin **bitte wiederholen**?","en":"Przepraszam, tu jest tak głośno. Czy mogłaby Pani powtórzyć godzinę spotkania?","why":"Grzeczna prośba: *Könnten Sie* … bezokolicznik *wiederholen* na końcu. *der Termin* to tutaj godzina spotkania.","source":"hueber"},{"label":"d","lead":"◆ D… i… S… etwas f…?  ○ Ja, gern.  ◆ W… S…, o… es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","text":"◆ ___ etwas ___? ○ Ja, gern. ◆ ___, ___ es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","gaps":[["Darf ich Sie"],["fragen"],["Wissen Sie"],["ob"]],"solution":"◆ **Darf ich Sie** etwas **fragen**? ○ Ja, gern. ◆ **Wissen Sie**, **ob** es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","en":"Czy mogę Pana o coś zapytać? – Tak, oczywiście. – Czy wie Pan, czy w pociągu do Genewy o 14.33 jest też bistro albo wagon restauracyjny?","why":"*Darf ich Sie etwas fragen?* grzecznie otwiera rozmowę; *ob* zaczyna zależne pytanie typu tak/nie, więc *gibt* idzie na koniec.","source":"hueber"}]},{"no":"15","tag":"C2","instruction":"Bilden Sie Wörter und ordnen Sie zu.","instruction_en":"Ułóż słowa z sylab w ramce i uzupełnij zdania. Przekreślone sylaby (Men, sa) są użyte w przykładzie.","phrases":["schrei · druck · ni · lung · ker · der · auf · Aus · ben · ho · Me · Wie · cha  (durchgestrichen im Beispiel: Men, sa)"],"example":[{"label":"a","text":"Ich wähle in der **Mensa** immer ein vegetarisches Gericht."}],"items":[{"label":"b","text":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten ___ geben? Diesmal will ich sie mir gleich in meinem Adressbuch ___, damit ich sie nicht wieder verliere.","gaps":[["Mechaniker"],["aufschreiben"]],"solution":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten **Mechaniker** geben? Diesmal will ich sie mir gleich in meinem Adressbuch **aufschreiben**, damit ich sie nicht wieder verliere.","en":"Mój samochód znowu się zepsuł. Czy mógłbyś mi jeszcze raz dać numer telefonu do twojego dobrego mechanika? Tym razem chcę go od razu zapisać w notesie z adresami, żeby znowu go nie zgubić.","why":"Me-cha-ni-ker (osoba, która naprawia samochody) i auf-schrei-ben (bezokolicznik na końcu po *will*).","source":"hueber"},{"label":"c","text":"Was bedeutet der ___ «eine Entscheidung treffen»? Den habe ich noch nie gehört.","gaps":[["Ausdruck"]],"solution":"Was bedeutet der **Ausdruck** «eine Entscheidung treffen»? Den habe ich noch nie gehört.","en":"Co znaczy wyrażenie „eine Entscheidung treffen”? Nigdy go nie słyszałem.","why":"Aus-druck: *der Ausdruck* = wyrażenie; *der* i *Den* pokazują, że to rodzaj męski. (*eine Entscheidung treffen* = podjąć decyzję.)","source":"hueber"},{"label":"d","text":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur ___.","gaps":[["Wiederholung"]],"solution":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur **Wiederholung**.","en":"Niestety często zapominam ważne niemieckie słowa. Potrzebuję więcej czasu na powtórki.","why":"Wie-der-ho-lung: *zur* = *zu der*, więc dalej stoi rzeczownik rodzaju żeńskiego: *die Wiederholung* (powtórka, powtarzanie).","source":"hueber"}]}]},{"page":"AB 134","heading":"D  Fremdsprachen lernen – aber wie?","heading_en":"Nauka języków obcych – ale jak?","exercises":[{"no":"16","tag":"D1","instruction":"Fremdsprachen lernen – aber wie?","instruction_en":"Nauka języków obcych – ale jak?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ordnen Sie zu.","part_instruction_en":"Kto co mówi? Przeczytaj trzy teksty i po każdym zdaniu napisz literę tekstu (A, B lub C).","reading":[{"label":"A  Mila, 17 Jahre","text":"Ich finde es total wichtig, dass man neue Wörter lernt und sie immer wieder wiederholt. Ich schreibe sie auf kleine Zettel oder Karten, auf der einen Seite das fremdsprachige Wort und auf der anderen die Übersetzung in meine Muttersprache. Diese Wortkarten habe ich immer in meiner Handtasche. Jeden Tag fahre ich eine Stunde mit dem Zug zur Schule. Das ist langweilig. Da habe ich viel Zeit und dann hole ich meine Wortkarten heraus und wiederhole die Wörter."},{"label":"B  Hakan, 19 Jahre","text":"Ich lerne seit vier Jahren Englisch in der Schule. Mir hilft es sehr, wenn ich viel Englisch höre. Ich habe viele MP3s mit Übungen aus dem Englischbuch und für die Aussprache auf meinem Smartphone. Ausserdem habe ich im Internet gute englische Podcasts gefunden. Die höre ich, wenn ich unterwegs bin. Ich möchte irgendwann nach der Schule ein Jahr nach London gehen und mir dort einen Job suchen. Darum will ich gut Englisch sprechen und auch meine Aussprache verbessern."},{"label":"C  Danila, 16 Jahre","text":"Ich bin vor drei Jahren in die Schweiz gekommen. Jetzt kann ich schon ziemlich gut Deutsch. Viel Zuhören ist für mich am allerwichtigsten. Deswegen habe ich im Bus, auf der Strasse, einfach überall immer den Schweizern zugehört und viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien. So habe ich viele Wörter und kleine Sätze der Alltagssprache gelernt, sogar auf Dialekt. Immer nur Grammatik und Wörter lernen, das finde ich uninteressant."}],"example":[{"label":"1","text":"Ich möchte meine Aussprache verbessern. → **B**"}],"items":[{"label":"2","text":"Ich höre oft anderen Leuten zu. → ___","gaps":[["C","Danila"]],"solution":"Ich höre oft anderen Leuten zu. → **C**","en":"Często słucham innych ludzi. → C (Danila)","why":"Danila: *Deswegen habe ich … einfach überall immer den Schweizern zugehört.*","source":"hueber"},{"label":"3","text":"Auf dem Weg zur Schule lerne ich Wörter. → ___","gaps":[["A","Mila"]],"solution":"Auf dem Weg zur Schule lerne ich Wörter. → **A**","en":"W drodze do szkoły uczę się słówek. → A (Mila)","why":"Mila wyjmuje fiszki podczas godzinnej jazdy pociągiem do szkoły.","source":"hueber"},{"label":"4","text":"Ich möchte nach der Schule in England arbeiten. → ___","gaps":[["B","Hakan"]],"solution":"Ich möchte nach der Schule in England arbeiten. → **B**","en":"Po szkole chciałbym pracować w Anglii. → B (Hakan)","why":"Hakan: *… ein Jahr nach London gehen und mir dort einen Job suchen.*","source":"hueber"},{"label":"5","text":"Ich schaue viel deutschsprachiges Fernsehen. → ___","gaps":[["C","Danila"]],"solution":"Ich schaue viel deutschsprachiges Fernsehen. → **C**","en":"Oglądam dużo niemieckojęzycznej telewizji. → C (Danila)","why":"Danila: *… viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien.*","source":"hueber"},{"label":"6","text":"Ich schreibe Wortkarten. → ___","gaps":[["A","Mila"]],"solution":"Ich schreibe Wortkarten. → **A**","en":"Piszę fiszki ze słówkami. → A (Mila)","why":"Mila pisze obce słowo po jednej stronie kartki, a tłumaczenie po drugiej.","source":"hueber"}]},{"no":"16","part":"b","part_instruction":"Schreiben Sie Sätze.","part_instruction_en":"Napisz drugie zdanie: zacznij od podanego słowa (Deshalb, Darum …) i użyj słów w nawiasach. Czasownik stoi zaraz po słowie na początku.","example":[{"label":"1","lead":"Mila möchte viele neue Wörter lernen. (neue Wörter auf Wortkarten schreiben)","text":"Deshalb **schreibt sie neue Wörter auf Wortkarten**."}],"items":[{"label":"2","lead":"Mila findet den Weg zur Schule langweilig. (mit Wortkarten neue Wörter wiederholen)","text":"","accept":["Darum wiederholt sie neue Wörter mit Wortkarten.","Darum wiederholt sie mit Wortkarten neue Wörter."],"solution":"**Darum wiederholt sie neue Wörter mit Wortkarten.**","en":"Dlatego powtarza nowe słówka za pomocą fiszek.","why":"*Darum* zajmuje pierwsze miejsce, więc zaraz po nim stoi odmieniony czasownik *wiederholt*, a potem podmiot *sie*.","source":"darum"},{"label":"3","lead":"Hakan hilft es, wenn er viel Englisch hört. (viele Podcasts auf seinem Smartphone haben)","text":"","accept":["Aus diesem Grund hat er viele Podcasts auf seinem Smartphone."],"solution":"**Aus diesem Grund hat er viele Podcasts auf seinem Smartphone.**","en":"Z tego powodu ma w smartfonie dużo podcastów.","why":"*Aus diesem Grund* zajmuje pierwsze miejsce tak jak *deshalb*: zaraz potem czasownik *hat*, potem *er*.","source":"hueber"},{"label":"4","lead":"Hakan möchte nach der Schule ein Jahr in London arbeiten. (gut Englisch sprechen wollen)","text":"","accept":["Deswegen will er gut Englisch sprechen."],"solution":"**Deswegen will er gut Englisch sprechen.**","en":"Dlatego chce dobrze mówić po angielsku.","why":"*Deswegen* + czasownik modalny *will* na drugim miejscu, bezokolicznik *sprechen* na końcu.","source":"deswegen"},{"label":"5","lead":"Danila findet Grammatik und Wörter lernen uninteressant. (viel deutschsprachiges Fernsehen schauen)","text":"","accept":["Daher schaut sie viel deutschsprachiges Fernsehen."],"solution":"**Daher schaut sie viel deutschsprachiges Fernsehen.**","en":"Dlatego ogląda dużo niemieckojęzycznej telewizji.","why":"*Daher* znaczy to samo co *deshalb*; czasownik *schaut* stoi zaraz po nim.","source":"deshalb"},{"label":"6","lead":"Für Danila ist Zuhören am allerwichtigsten. (einfach überall immer den Schweizern zugehört)","text":"","accept":["Aus diesem Grund hört sie einfach überall immer den Schweizern zu.","Aus diesem Grund hat sie einfach überall immer den Schweizern zugehört."],"solution":"**Aus diesem Grund hört sie einfach überall immer den Schweizern zu.**","en":"Z tego powodu po prostu zawsze i wszędzie słucha Szwajcarów.","why":"*zuhören* jest czasownikiem rozdzielnie złożonym: *hört … zu*. Polecenie podaje *zugehört*, więc Perfekt *hat … zugehört* (jak w tekście Danili) też jest poprawny.","source":"hueber","check":"Oficjalny klucz podaje czas teraźniejszy (*hört … zu*), chociaż polecenie podaje imiesłów *zugehört*. Oba zdania są poprawne po niemiecku; zapytaj nauczyciela, którą wersję chce książka."}]}]},{"page":"AB 138","heading":"Test Lektion 4","heading_en":"Test z lekcji 4","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij tekst Arifa. Książka podaje pierwszą literę i kilka liter w środku każdego słowa; wpisz całe słowo.","reading":[{"text":"Ich heisse Arif und bin 16 Jahre alt. Meine Familie und ich stammen (a) aus Syrien und unsere M… (b) ist Arabisch. Jetzt lerne ich seit einem Jahr Deutsch. Nächstes Jahr möchte ich eine Lehre beginnen. D… (c) möchte ich mein Deutsch verbessern. Natürlich spreche ich dann noch nicht f… (d) Deutsch. Besonders die Schrift und die A… (e) finde ich schwierig und ich verstehe auch noch nicht alle A… (f). Aber ich bin optimistisch."}],"example":[{"label":"a","text":"Meine Familie und ich **stammen** aus Syrien."}],"items":[{"label":"b","lead":"… und unsere M _ t _ _ _ s _ _ _ c _ _ ist Arabisch.","text":"… und unsere ___ ist Arabisch.","gaps":[["Muttersprache"]],"solution":"… und unsere **Muttersprache** ist Arabisch.","en":"… a naszym językiem ojczystym jest arabski.","why":"*die Muttersprache* = pierwszy język, z którym się dorasta."},{"label":"c","lead":"D _ _ _ e _ e _ möchte ich mein Deutsch verbessern.","text":"___ möchte ich mein Deutsch verbessern.","gaps":[["Deswegen"]],"solution":"**Deswegen** möchte ich mein Deutsch verbessern.","en":"Dlatego chciałbym poprawić swój niemiecki.","why":"Układ liter (D, e, e) pasuje do *Deswegen*; podaje skutek, a czasownik *möchte* stoi zaraz po nim.","source":"deswegen"},{"label":"d","lead":"Natürlich spreche ich dann noch nicht f _ _ _ _ _ e _ _ Deutsch.","text":"Natürlich spreche ich dann noch nicht ___ Deutsch.","gaps":[["fliessend"]],"solution":"Natürlich spreche ich dann noch nicht **fliessend** Deutsch.","en":"Oczywiście nie będę wtedy jeszcze mówić płynnie po niemiecku.","why":"*fliessend* = płynny, płynnie. Pisownia szwajcarska z *ss*."},{"label":"e","lead":"Besonders die Schrift und die A _ _ _ p _ _ _ _ e finde ich schwierig …","text":"Besonders die Schrift und die ___ finde ich schwierig …","gaps":[["Aussprache"]],"solution":"Besonders die Schrift und die **Aussprache** finde ich schwierig …","en":"Szczególnie trudne wydają mi się pismo i wymowa …","why":"*die Aussprache* = wymowa (*aussprechen* = wymawiać)."},{"label":"f","lead":"… und ich verstehe auch noch nicht alle A _ _ d _ _ c _ e.","text":"… und ich verstehe auch noch nicht alle ___.","gaps":[["Ausdrücke"]],"solution":"… und ich verstehe auch noch nicht alle **Ausdrücke**.","en":"… i też jeszcze nie rozumiem wszystkich wyrażeń.","why":"*der Ausdruck, die Ausdrücke* = wyrażenie, wyrażenia; *alle* wymaga liczby mnogiej."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit wenn.","instruction_en":"Napisz nierzeczywiste zdania warunkowe z *wenn* i trybem przypuszczającym Konjunktiv II (*wäre, hätte, könnte, müsste* lub *würde* + bezokolicznik).","example":[{"label":"a","lead":"(ich heute nicht so viel vorhaben – spazieren gehen)","text":"Wenn **ich heute nicht so viel vorhätte, würde ich spazieren gehen**."}],"items":[{"label":"b","lead":"(ich mein Englisch besser sein – dir bei der Hausaufgabe helfen können)","text":"","accept":["Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.","Wenn mein Englisch besser wäre, würde ich dir bei der Hausaufgabe helfen können."],"solution":"**Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.**","en":"Gdyby mój angielski był lepszy, mógłbym ci pomóc w zadaniu domowym.","why":"*sein* → **wäre** na końcu zdania z *wenn*; *können* → **könnte**, potem zdanie główne zaczyna się od czasownika.","source":"kond"},{"label":"c","lead":"(ich euch besser verstehen – ihr nicht durcheinander sprechen)","text":"","accept":["Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.","Ich würde euch besser verstehen, wenn ihr nicht durcheinandersprechen würdet.","Ich könnte euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet."],"solution":"**Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.**","en":"Lepiej bym was rozumiał, gdybyście nie mówili wszyscy naraz.","why":"Najpierw zdanie główne; *würde* + bezokolicznik w obu częściach. W zdaniu z *wenn* forma *würdet* idzie na koniec.","source":"kond"},{"label":"d","lead":"(ich mehr Freizeit haben – nicht so viel arbeiten müssen)","text":"","accept":["Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste."],"solution":"**Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste.**","en":"Miałbym więcej czasu wolnego, gdybym nie musiał tyle pracować.","why":"*haben* → **hätte**, *müssen* → **müsste** (na końcu zdania z *wenn*).","source":"k2"}]},{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij słowem z ramki. Każde słowo jest użyte raz; przekreślone jest użyte w przykładzie (odpowiedź do a).","box":["denn","Weshalb","Weil","Wegen","Deswegen"],"box_used":[2],"box_exact":true,"items":[{"label":"a","text":"___ möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","gaps":[["Weshalb"]],"solution":"**Weshalb** möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","en":"Dlaczego Costa chce zostać mechatronikiem? – Bo interesuje się samochodami.","why":"Potrzebny jest zaimek pytający; **Weshalb** = *warum* (dlaczego). Wydrukowana odpowiedź zaczyna się od *Weil*.","source":"weil"},{"label":"b","text":"___ seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","gaps":[["Wegen"]],"solution":"**Wegen** seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","en":"Dzięki dobrej znajomości niemieckiego szybko znalazł miejsce nauki zawodu.","why":"Dalej stoi grupa rzeczownikowa (*seiner guten Deutschkenntnisse*, dopełniacz liczby mnogiej) → przyimek **Wegen**.","source":"wegen"},{"label":"c","text":"Er ist erst 17 Jahre alt. ___ wohnt er noch bei seinen Eltern.","gaps":[["Deswegen"]],"solution":"Er ist erst 17 Jahre alt. **Deswegen** wohnt er noch bei seinen Eltern.","en":"Ma dopiero 17 lat. Dlatego wciąż mieszka u rodziców.","why":"Skutek, a czasownik stoi zaraz po luce (*wohnt er*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Jetzt spart er Geld, ___ er möchte nach der Ausbildung eine eigene Wohnung haben.","gaps":[["denn"]],"solution":"Jetzt spart er Geld, **denn** er möchte nach der Ausbildung eine eigene Wohnung haben.","en":"Teraz oszczędza pieniądze, bo po nauce zawodu chciałby mieć własne mieszkanie.","why":"Przyczyna, a czasownik zostaje na drugim miejscu (*er möchte*) → **denn**.","source":"denn"}]},{"no":"4","instruction":"Wie kann man auch sagen? Ergänzen Sie.","instruction_en":"Jak inaczej można to powiedzieć? Uzupełnij drugi zwrot. Książka podaje kilka liter; wpisz całe słowa.","example":[{"label":"a","text":"Können Sie mir sagen, wo …? – **Wissen Sie**, wo …?"}],"items":[{"label":"b","lead":"Ich habe eine Frage. – D _ _ _  i _ _  S _ _  e _ _ _ _  f _ _ _ _ _?","text":"Ich habe eine Frage. – ___?","gaps":[["Darf ich Sie etwas fragen"]],"solution":"Ich habe eine Frage. – **Darf ich Sie etwas fragen**?","en":"Mam pytanie. – Czy mogę Pana o coś zapytać?","why":"Grzeczny sposób, żeby zacząć pytanie: *Darf ich Sie etwas fragen?*"},{"label":"c","lead":"Könnten Sie das bitte noch einmal sagen? – K _ _ _ t _ _  S _ _  d _ s  b _ _ t _  wi _ _ _ h _ _ _ _?","text":"Könnten Sie das bitte noch einmal sagen? – ___?","gaps":[["Könnten Sie das bitte wiederholen"]],"solution":"Könnten Sie das bitte noch einmal sagen? – **Könnten Sie das bitte wiederholen**?","en":"Czy mógłby Pan to jeszcze raz powiedzieć? – Czy mógłby Pan to powtórzyć?","why":"*wiederholen* = powtórzyć = *noch einmal sagen*."},{"label":"d","lead":"Was meinen Sie mit …? – W _ _  b _ _ e _ _ _ _ …?","text":"Was meinen Sie mit …? – ___ …?","gaps":[["Was bedeutet"]],"solution":"Was meinen Sie mit …? – **Was bedeutet** …?","en":"Co ma Pan na myśli, mówiąc …? – Co znaczy …?","why":"*Was bedeutet …?* pyta o znaczenie, tak jak *Was meinen Sie mit …?*","check":"Litery w tej luce są na zdjęciu słabo czytelne; *Was bedeutet …?* do nich pasuje i jest zwrotem z ćwiczenia 13. Zapytaj nauczyciela, jeśli w twojej książce jest coś innego."},{"label":"e","lead":"Entschuldigung. – T _ _  m _ _  l _ _ _.","text":"Entschuldigung. – ___.","gaps":[["Tut mir leid"]],"solution":"Entschuldigung. – **Tut mir leid**.","en":"Przepraszam. – Przykro mi.","why":"*Tut mir leid* = przykro mi, inny sposób, żeby przeprosić."}]}]},{"page":"AB 139","heading":"Fokus Beruf: Stellensuche","heading_en":"Praca w centrum uwagi: szukanie pracy","exercises":[{"no":"1","instruction":"Yusuf sucht eine neue Stelle als Coiffeur. Er liest eine Broschüre mit Tipps für die Stellensuche. Lesen Sie die Tipps und ordnen Sie die Überschriften zu.","instruction_en":"Yusuf szuka nowej pracy jako fryzjer. Czyta broszurę ze wskazówkami, jak szukać pracy. Przeczytaj wskazówki i po każdym akapicie napisz literę pasującego nagłówka (A–E).","reading":[{"label":"1","text":"Machen Sie eine Liste von Personen, die Sie persönlich kennen: Bekannte, Kollegen, Freunde und Verwandte. Notieren Sie auch die Namen von früheren Arbeitgebern und Arbeitskollegen. Informieren Sie diese Personen – mündlich oder schriftlich – darüber, dass Sie auf Stellensuche sind. Wichtig: Informieren Sie Ihre Kontaktpersonen, wenn Sie eine Stelle gefunden haben."},{"label":"2","text":"Werden Sie aktiv. Warten Sie nicht, bis Sie ein passendes Stelleninserat finden, sondern schreiben Sie Ihre eigene Stellenanzeige. Suchen Sie ein Internet-Portal, das zu Ihrer Branche passt, und präsentieren Sie sich. Solche Annoncen kosten viel weniger als gedruckte Annoncen und Sie können sie ausserdem noch mit einer eigenen Bewerber-Website verbinden."},{"label":"3","text":"Erhöhen Sie Ihre Erfolgschancen mit einer Kurzbewerbung. Suchen Sie sich Ihre Wunschfirma und bewerben Sie sich. Dafür braucht es natürlich eine gute Recherche, damit Sie die «richtige» Firma und die «richtige» Person anschreiben. Wie ihr Name sagt, ist diese Bewerbung kurz: Sie besteht aus einem Bewerbungsschreiben und dem tabellarischen Lebenslauf."},{"label":"4","text":"Sind in Ihrer Branche Bewerbungen per Telefon üblich? Sind Sie besonders mutig und überzeugen vor allem mündlich sehr gut? Aus welchem Grund Sie sich für diese Bewerbungsform entscheiden: Wichtig ist auch hier eine gründliche Vorbereitung. Machen Sie Notizen und üben Sie das Gespräch mit Freunden. Fehlt Ihnen der Mut dazu, wählen Sie die schriftliche Bewerbung."},{"label":"5","text":"Die grösste Auswahl an Stelleninseraten finden Sie im Internet. Wichtig ist eine sorgfältige Analyse der Inserate: Was will die Firma? Welche Qualifikationen und Erfahrungen haben Sie? Machen Sie eine Liste und beantworten Sie diese Fragen. Können Sie ca. 80 Prozent der Anforderungen erfüllen, dann ist eine Bewerbung sinnvoll."}],"items":[{"label":"1","text":"Absatz 1 (Liste von Personen, die Sie kennen) → ___","gaps":[["C","C Das persönliche Netzwerk"]],"solution":"Absatz 1 (Liste von Personen, die Sie kennen) → **C**","en":"Akapit 1 (lista osób, które znasz) → C, Twoja osobista sieć kontaktów","why":"Przyjaciele, koledzy z pracy i byli pracodawcy to twoja osobista sieć kontaktów.","source":"hueber"},{"label":"2","text":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → ___","gaps":[["A","A Online-Stellengesuch"]],"solution":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → **A**","en":"Akapit 2 (twoje własne ogłoszenie w internecie) → A, Ogłoszenie o szukaniu pracy w internecie","why":"*das Stellengesuch* = ogłoszenie, w którym szukasz pracy; tutaj na portalu internetowym.","source":"hueber"},{"label":"3","text":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → ___","gaps":[["E","E Spontanbewerbung"]],"solution":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → **E**","en":"Akapit 3 (krótkie podanie o pracę do wymarzonej firmy) → E, Aplikacja z własnej inicjatywy","why":"Zgłaszasz się do firmy, która nie ogłosiła oferty pracy: *die Spontanbewerbung*.","source":"hueber"},{"label":"4","text":"Absatz 4 (Bewerbungen per Telefon) → ___","gaps":[["D","D Telefonische Bewerbung"]],"solution":"Absatz 4 (Bewerbungen per Telefon) → **D**","en":"Akapit 4 (ubieganie się o pracę przez telefon) → D, Ubieganie się o pracę przez telefon","why":"*per Telefon* = *telefonisch*.","source":"hueber"},{"label":"5","text":"Absatz 5 (Stelleninserate im Internet analysieren) → ___","gaps":[["B","B Stelleninserate"]],"solution":"Absatz 5 (Stelleninserate im Internet analysieren) → **B**","en":"Akapit 5 (analiza ogłoszeń o pracę w internecie) → B, Ogłoszenia o pracę","why":"*das Stelleninserat* (szwajcarskie słowo) = ogłoszenie o pracę zamieszczone przez firmę.","source":"hueber"}],"phrases":["A Online-Stellengesuch","B Stelleninserate","C Das persönliche Netzwerk","D Telefonische Bewerbung","E Spontanbewerbung"]},{"no":"2","instruction":"Yusuf hat entschieden, selbst aktiv zu werden, und hat ein Stellengesuch geschrieben. Lesen Sie seinen Text und unterstreichen Sie: – Wer und wie ist Yusuf? – Was kann er? – Was sucht er?","instruction_en":"Yusuf postanowił wziąć sprawy w swoje ręce i napisał ogłoszenie, że szuka pracy. Przeczytaj jego tekst i znajdź: kim jest Yusuf i jaki jest, co potrafi i czego szuka. Przy każdym pytaniu wypisz pasujące słowa.","reading":[{"text":"Suchen Sie einen engagierten Coiffeur, der kreativ und flexibel ist? Dann rufen Sie mich, 24, an. Ich biete sechs Jahre Berufserfahrung und diverse Weiterbildungen im Bereich Stilberatung. Ich suche eine Herausforderung, bei der ich Neues lernen und mich weiter spezialisieren kann."}],"items":[{"label":"1","lead":"Wer und wie ist Yusuf?","text":"","open":true,"solution":"ein engagierter Coiffeur, kreativ und flexibel, 24 Jahre alt","en":"zaangażowany fryzjer, kreatywny i elastyczny, 24 lata","why":"Kim jest (zawód, wiek) i jaki jest (przymiotniki).","source":"hueber"},{"label":"2","lead":"Was kann er?","text":"","open":true,"solution":"sechs Jahre Berufserfahrung, diverse Weiterbildungen im Bereich Stilberatung","en":"sześć lat doświadczenia zawodowego, różne szkolenia z doradztwa w zakresie stylu","why":"Co oferuje: doświadczenie i szkolenia.","source":"hueber"},{"label":"3","lead":"Was sucht er?","text":"","open":true,"solution":"eine Herausforderung, bei der er Neues lernen und sich weiter spezialisieren kann","en":"wyzwanie, przy którym może nauczyć się nowych rzeczy i dalej się specjalizować","why":"Ostatnie zdanie: *Ich suche …*","source":"hueber"}]},{"no":"3","instruction":"Ein Stellengesuch im Internet aufgeben. Sie suchen eine neue Stelle. Machen Sie eine Tabelle. Schreiben Sie dann einen Profiltext wie in 2.","instruction_en":"Zamieść w internecie ogłoszenie o poszukiwaniu pracy. Szukasz nowej pracy. Zrób tabelę z trzema kolumnami (Kim jestem i jaki/jaka jestem? Co potrafię? Czego szukam?), potem napisz tekst profilu taki jak tekst Yusufa w 2. Przykładowa odpowiedź to jedna z możliwości.","phrases":["teamfähig/selbstständig/kontaktfreudig/zuverlässig/verantwortungsbewusst / … sein","gute Computer-/Sprachkenntnisse/Kenntnisse in … haben","gut mit … umgehen können","… Vollzeit/Teilzeit/auf Stundenbasis arbeiten","ab sofort / ab nächstem Monat / … suchen"],"example":[{"label":"Tabelle","text":"Wer und wie bin ich? flexibel, teamfähig, … | Was kann ich? … | Was suche ich? …"}],"items":[{"label":"1","lead":"Tabelle","text":"","open":true,"solution":"Wer und wie bin ich? flexibel, teamfähig, zuverlässig, kontaktfreudig | Was kann ich? gut mit Kunden umgehen, gute Computerkenntnisse, fliessend Deutsch und Englisch | Was suche ich? eine Teilzeitstelle ab nächstem Monat, ein internationales Team","en":"Kim jestem i jaka jestem? elastyczna, umiejąca pracować w zespole, solidna, towarzyska | Co potrafię? dobrze obsługiwać klientów, dobra znajomość komputera, płynny niemiecki i angielski | Czego szukam? pracy na część etatu od przyszłego miesiąca, międzynarodowego zespołu","why":"Wystarczy kilka słów kluczowych w każdej kolumnie; użyj zwrotów z ramki.","source":"hueber"},{"label":"2","lead":"Profiltext","text":"","open":true,"solution":"Suchen Sie eine zuverlässige Verkäuferin, die teamfähig und kontaktfreudig ist? Ich kann gut mit Kunden umgehen, habe gute Computerkenntnisse und spreche fliessend Deutsch und Englisch. Ich suche ab nächstem Monat eine Teilzeitstelle in einem internationalen Team.","en":"Szukają Państwo solidnej sprzedawczyni, która umie pracować w zespole i jest towarzyska? Potrafię dobrze obsługiwać klientów, dobrze znam się na komputerach i mówię płynnie po niemiecku i angielsku. Od przyszłego miesiąca szukam pracy na część etatu w międzynarodowym zespole.","why":"Te same trzy kroki co u Yusufa: kim jesteś, co potrafisz, czego szukasz. *die* w zdaniu względnym odnosi się do *Verkäuferin*.","source":"hueber"}]}]},{"page":"Test L4 · 19","heading":"Grammatik","heading_en":"Gramatyka","exercises":[{"no":"1","instruction":"Wunsch und Realität?","instruction_en":"Życzenie i rzeczywistość?","part":"a","part_instruction":"Ergänzen Sie.","part_instruction_en":"Nina musi zrobić jedno, ale wolałaby zrobić coś innego. Napisz, co wolałaby robić, używając *würde* + słów w nawiasach (z *lieber*, a w punkcie 5 z *gern*).","example":[{"label":"1","lead":"Nina macht Diät. (Sahnetorte essen)","text":"Aber sie **würde lieber Sahnetorte essen**."}],"items":[{"label":"2","lead":"Nina muss für eine Sprachprüfung lernen. (Musik hören)","text":"Aber sie ___.","gaps":[["würde lieber Musik hören"]],"solution":"Aber sie **würde lieber Musik hören**.","en":"Ale wolałaby słuchać muzyki.","why":"*würde* na drugim miejscu, *lieber* = raczej, bezokolicznik *hören* na końcu.","source":"k2"},{"label":"3","lead":"Nina muss ihre Kleider aufräumen. (mit ihrer Freundin telefonieren)","text":"Aber sie ___.","gaps":[["würde lieber mit ihrer Freundin telefonieren"]],"solution":"Aber sie **würde lieber mit ihrer Freundin telefonieren**.","en":"Ale wolałaby porozmawiać przez telefon z przyjaciółką.","why":"*würde* + *lieber* + bezokolicznik na końcu.","source":"k2"},{"label":"4","lead":"Nina arbeitet am Computer. (Computerspiele spielen)","text":"Aber sie ___.","gaps":[["würde lieber Computerspiele spielen"]],"solution":"Aber sie **würde lieber Computerspiele spielen**.","en":"Ale wolałaby grać w gry komputerowe.","why":"*würde* + *lieber* + bezokolicznik na końcu.","source":"k2"},{"label":"5","lead":"Nina hat morgen sehr früh einen Termin. (bis spät in die Nacht lesen)","text":"Sie ___ gern ___.","gaps":[["würde aber"],["bis spät in die Nacht lesen"]],"solution":"Sie **würde aber** gern **bis spät in die Nacht lesen**.","en":"Ale chętnie czytałaby do późnej nocy.","why":"Książka podaje *gern*: *würde* + *gern* + bezokolicznik (życzenie), z *aber* po czasowniku.","source":"k2"},{"label":"6","lead":"Nina verbringt den Abend mit ihren Eltern. (tanzen gehen)","text":"Aber sie ___.","gaps":[["würde lieber tanzen gehen"]],"solution":"Aber sie **würde lieber tanzen gehen**.","en":"Ale wolałaby pójść potańczyć.","why":"*würde* + *lieber*; oba bezokoliczniki *tanzen gehen* na końcu.","source":"k2"}]},{"no":"1","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Przepisz zdania z a jako nierzeczywiste zdania warunkowe: *Wenn Nina nicht …, würde sie …*","example":[{"label":"1","text":"Wenn Nina nicht Diät machen würde, würde sie Sahnetorte essen."}],"items":[{"label":"2","text":"","accept":["Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören."],"solution":"**Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören.**","en":"Gdyby Nina nie musiała uczyć się do egzaminu językowego, słuchałaby muzyki.","why":"*muss* → **müsste** na końcu zdania z *wenn*; zdanie główne zaczyna się od *würde*.","source":"kond"},{"label":"3","text":"","accept":["Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.","Wenn Nina ihre Kleider nicht aufräumen müsste, würde sie mit ihrer Freundin telefonieren."],"solution":"**Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.**","en":"Gdyby Nina nie musiała sprzątać swoich ubrań, rozmawiałaby przez telefon z przyjaciółką.","why":"*müsste* + bezokolicznik *aufräumen*: w zdaniu z *wenn* *müsste* stoi na końcu.","source":"kond"},{"label":"4","text":"","accept":["Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.","Wenn Nina nicht am Computer arbeiten müsste, würde sie Computerspiele spielen."],"solution":"**Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.**","en":"Gdyby Nina nie pracowała przy komputerze, grałaby w gry komputerowe.","why":"Klucz akceptuje w zdaniu z *wenn* zarówno *arbeiten würde*, jak i *arbeiten müsste*."},{"label":"5","text":"","accept":["Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.","Wenn Nina morgen keinen Termin sehr früh hätte, würde sie bis spät in die Nacht lesen."],"solution":"**Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.**","en":"Gdyby Nina nie miała jutro bardzo wcześnie umówionego spotkania, czytałaby do późnej nocy.","why":"*hat* → **hätte**, na końcu zdania z *wenn*."},{"label":"6","text":"","accept":["Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.","Wenn Nina den Abend nicht mit ihren Eltern verbringen müsste, würde sie tanzen gehen."],"solution":"**Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.**","en":"Gdyby Nina nie spędzała wieczoru z rodzicami, poszłaby potańczyć.","why":"*würde* + bezokolicznik w obu częściach; *verbringen würde* na końcu zdania z *wenn*."}]},{"no":"2","instruction":"Ergänzen Sie: darum – weil – wegen.","instruction_en":"Uzupełnij słowem *darum*, *weil* lub *wegen*. Każde słowo jest użyte dwa razy.","box":["darum","weil","wegen"],"items":[{"label":"a","text":"Viele Deutsche hören Majids Grammatikfehler nicht, ___ er eine sehr gute Aussprache hat.","gaps":[["weil"]],"solution":"Viele Deutsche hören Majids Grammatikfehler nicht, **weil** er eine sehr gute Aussprache hat.","en":"Wielu Niemców nie słyszy błędów gramatycznych Majida, bo ma on bardzo dobrą wymowę.","why":"Przyczyna, a czasownik *hat* stoi na końcu → **weil**.","source":"weil"},{"label":"b","text":"Mirko hat die Prüfung nicht bestanden, ___ will er jetzt einen Intensivkurs machen.","gaps":[["darum"]],"solution":"Mirko hat die Prüfung nicht bestanden, **darum** will er jetzt einen Intensivkurs machen.","en":"Mirko nie zdał egzaminu, dlatego chce teraz zrobić kurs intensywny.","why":"Skutek, a czasownik *will* stoi zaraz po luce → **darum**.","source":"darum"},{"label":"c","text":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, ___ braucht er sehr gute Deutschkenntnisse.","gaps":[["darum"]],"solution":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, **darum** braucht er sehr gute Deutschkenntnisse.","en":"Hassan chce pracować jako lekarz w niemieckim szpitalu, dlatego potrzebuje bardzo dobrej znajomości niemieckiego.","why":"Skutek + czasownik zaraz po luce (*braucht er*) → **darum**.","source":"darum"},{"label":"d","text":"Camilla ist Managerin und kann ___ ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","gaps":[["wegen"]],"solution":"Camilla ist Managerin und kann **wegen** ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","en":"Camilla jest menedżerką i z powodu wielu konferencji nie może regularnie chodzić na kurs niemieckiego.","why":"Dalej stoi grupa rzeczownikowa (*ihrer vielen Konferenzen*, dopełniacz liczby mnogiej) → **wegen**.","source":"wegen"},{"label":"e","text":"Boris wird ___ seines Akzents sofort als Russe erkannt.","gaps":[["wegen"]],"solution":"Boris wird **wegen** seines Akzents sofort als Russe erkannt.","en":"Borisa z powodu akcentu od razu rozpoznaje się jako Rosjanina.","why":"Grupa rzeczownikowa w dopełniaczu (*seines Akzents*) → **wegen**.","source":"wegen"},{"label":"f","text":"Anja würde gern Arabisch lernen, ___ sie die arabische Schrift so schön findet.","gaps":[["weil"]],"solution":"Anja würde gern Arabisch lernen, **weil** sie die arabische Schrift so schön findet.","en":"Anja chętnie nauczyłaby się arabskiego, bo pismo arabskie wydaje jej się takie piękne.","why":"Przyczyna z czasownikiem *findet* na końcu → **weil**.","source":"weil"}]}]},{"page":"Test L4 · 20","heading":"Wortschatz","heading_en":"Słownictwo","exercises":[{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij tekst Ferdeza słowami z ramki. Każde słowo jest użyte raz; przekreślone jest użyte w przykładzie. Karta pracy używa pisowni z Niemiec z ostrym s; tutaj jest pisownia szwajcarska z *ss* (*fliessend*).","box":["Akzent","fliessend","schimpfe","Muttersprache","Schrift","übersetzen","vergleiche"],"box_used":[3],"box_exact":true,"example":[{"label":"a","text":"Mein Name ist Ferdez. Ich komme aus Mazedonien. Meine **Muttersprache** ist Albanisch, aber ich spreche auch Mazedonisch."}],"items":[{"label":"b","text":"Im Mazedonischen wird die kyrillische ___ verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","gaps":[["Schrift"]],"solution":"Im Mazedonischen wird die kyrillische **Schrift** verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","en":"W macedońskim używa się cyrylicy. Dlatego na początku nie było mi łatwo pisać po niemiecku.","why":"*die kyrillische Schrift* = cyrylica."},{"label":"c","text":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich ___ Deutsch, finde ich.","gaps":[["fliessend"]],"solution":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich **fliessend** Deutsch, finde ich.","en":"Od ośmiu lat mieszkam w Bawarii. Teraz mówię już płynnie po niemiecku, tak uważam.","why":"*fliessend Deutsch sprechen* = mówić płynnie po niemiecku."},{"label":"d","text":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen ___ habe!","gaps":[["Akzent"]],"solution":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen **Akzent** habe!","en":"Ale moi koledzy z północnych Niemiec mówią, że mam bawarski akcent!","why":"*einen … Akzent haben* = mieć akcent; *einen bayerischen* → rzeczownik rodzaju męskiego."},{"label":"e","text":"Wenn ich auf Bayerisch ___, lachen meine Kollegen sich kaputt.","gaps":[["schimpfe"]],"solution":"Wenn ich auf Bayerisch **schimpfe**, lachen meine Kollegen sich kaputt.","en":"Kiedy klnę po bawarsku, moi koledzy pękają ze śmiechu.","why":"*schimpfen* = narzekać, kląć; *ich schimpfe* na końcu zdania z *wenn*."},{"label":"f","text":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander ___, dann fällt mir auf, …","gaps":[["vergleiche"]],"solution":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander **vergleiche**, dann fällt mir auf, …","en":"Kiedy porównuję ze sobą niemiecki, macedoński i albański, zauważam, …","why":"*miteinander vergleichen* = porównywać ze sobą; *ich vergleiche* na końcu zdania z *wenn*."},{"label":"g","text":"… dass man nicht alle Wörter wirklich gut in die andere Sprache ___ kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","gaps":[["übersetzen"]],"solution":"… dass man nicht alle Wörter wirklich gut in die andere Sprache **übersetzen** kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","en":"… że nie wszystkie słowa da się naprawdę dobrze przetłumaczyć na drugi język. Dziś czuję się jak w domu i w Macedonii, i w Niemczech.","why":"*in eine Sprache übersetzen* = tłumaczyć na jakiś język; bezokolicznik przed *kann* na końcu zdania z *dass*."}]},{"no":"Pause","instruction":"Was bedeutet das? Kreuzen Sie an. «Lügen haben kurze Beine.»","instruction_en":"Co znaczy przysłowie „Lügen haben kurze Beine“ (kłamstwa mają krótkie nogi)? Wpisz A lub B.","items":[{"label":"A/B","lead":"A Die Wahrheit kommt immer schnell ans Licht. Darum sollte man nicht lügen.  B Wer lügt, der bekommt zur Strafe kurze Beine.","text":"___","gaps":[["A"]],"solution":"**A**","en":"A: Prawda zawsze szybko wychodzi na jaw. Dlatego nie należy kłamać.","why":"Kłamstwo nie zajdzie daleko, jak ktoś na krótkich nogach: szybko wychodzi na jaw. B to żart z dosłownego znaczenia słów."}]},{"no":"4","instruction":"Welches Wort passt auch? Notieren Sie.","instruction_en":"Które słowo z ramki mogłoby zastąpić podkreślone słowo? Napisz je. Każde słowo jest użyte raz; przekreślone jest użyte w przykładzie. Podkreślone słowa są tu pogrubione.","box":["allerdings","allmählich","aufschreiben","deswegen","ebenso","irgendwann","korrekt","stammt"],"box_used":[7],"box_exact":true,"example":[{"label":"a","text":"Meine Familie **kommt** aus Iran. → stammt"}],"items":[{"label":"b","lead":"Ich selbst bin **aber** in Mainz geboren.","text":"___","gaps":[["allerdings"]],"solution":"**allerdings**","en":"Ja sam urodziłem się jednak w Moguncji.","why":"*allerdings* = *aber*: ogranicza to, co powiedziano wcześniej."},{"label":"c","lead":"Mit mir haben meine Eltern immer Deutsch gesprochen, **deshalb** kann ich leider nicht Farsi.","text":"___","gaps":[["deswegen"]],"solution":"**deswegen**","en":"Rodzice zawsze mówili do mnie po niemiecku, dlatego niestety nie znam farsi.","why":"*deswegen* = *deshalb* (skutek, czasownik stoi zaraz potem).","source":"deswegen"},{"label":"d","lead":"Jetzt nehme ich an einem Sprachkurs teil. Ich finde, Farsi ist **genauso** schwierig wie Deutsch.","text":"___","gaps":[["ebenso"]],"solution":"**ebenso**","en":"Teraz chodzę na kurs językowy. Uważam, że farsi jest tak samo trudny jak niemiecki.","why":"*ebenso … wie* = *genauso … wie* = tak samo … jak."},{"label":"e","lead":"Besonders die Schrift! Ich bin ein Mensch, der sich alle neuen Wörter **notieren** muss.","text":"___","gaps":[["aufschreiben"]],"solution":"**aufschreiben**","en":"Zwłaszcza pismo! Jestem kimś, kto musi zapisywać wszystkie nowe słowa.","why":"*sich etwas notieren* = *sich etwas aufschreiben* = zapisać coś sobie."},{"label":"f","lead":"Das ist schwierig, wenn man es in einer Schrift tun muss, die man auch erst **langsam** lernt.","text":"___","gaps":[["allmählich"]],"solution":"**allmählich**","en":"To trudne, kiedy musisz to robić w piśmie, którego dopiero stopniowo się uczysz.","why":"*allmählich* = powoli, krok po kroku, stopniowo."},{"label":"g","lead":"Auch die Aussprache ist nicht leicht. Es gibt da diesen Laut «gh», den kann ich nicht **richtig** aussprechen.","text":"___","gaps":[["korrekt"]],"solution":"**korrekt**","en":"Wymowa też nie jest łatwa. Jest taki dźwięk „gh”, którego nie umiem poprawnie wymówić.","why":"*korrekt* = *richtig* = poprawnie."},{"label":"h","lead":"**Eines Tages** klappt es – hoffe ich jedenfalls!","text":"___","gaps":[["irgendwann","Irgendwann"]],"solution":"**irgendwann**","en":"Kiedyś się uda – przynajmniej mam taką nadzieję!","why":"*irgendwann* = kiedyś, pewnego dnia = *eines Tages*."}]}]},{"page":"Test L4 · 21","heading":"Lesen","heading_en":"Czytanie","exercises":[{"no":"5","instruction":"Lesen Sie und kreuzen Sie an: Was ist richtig?","instruction_en":"Przeczytaj odpowiedzi na ankietę „Czy nauka niemieckiego jest ważna?” i wybierz właściwe zakończenie każdego zdania. Wpisz zakończenie (albo tylko jego pierwsze słowa).","reading":[{"label":"Brad, 30, aus Australien","text":"«Meine Freundin ist Deutsche. Deshalb bin ich vor einem Jahr nach Deutschland gekommen. Ich dachte, dass ich mit Englisch als Muttersprache keine Schwierigkeiten haben würde, einen Job zu finden. Aber immer wenn ich mich bewarb, bekam ich zur Antwort: Lernen Sie erst einmal richtig Deutsch. Dann können Sie wiederkommen. Offenbar glauben die Leute, dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht. Seit sechs Monaten besuche ich nun einen Deutschkurs.»"},{"label":"Alena, 24, aus Tschechien","text":"«Meine Grossmutter hat 30 Jahre in Wien gelebt. Ich habe sie als Kind oft besucht und Wien dabei sehr gut kennengelernt. Ich denke, ich habe in Wien bessere Karrierechancen als bei uns zu Hause. Darum habe ich jetzt das Zertifikat Deutsch gemacht. Mit dem Zertifikat habe ich bestimmt gute Chancen, wenn ich mich bei österreichischen Firmen bewerbe.»"},{"label":"Ewa, 23, aus Polen","text":"«Ich finde es aus historischen Gründen wichtig, Deutsch zu lernen. Denn Polen und Deutschland verbindet eine lange Geschichte, die nicht immer schön war. Aber gerade deshalb ist es wichtig, dass wir uns gegenseitig gut kennenlernen. Ich würde mir wünschen, dass auch mehr Deutsche sich für die polnische Sprache interessieren würden.»"},{"label":"Sopha, 32, aus Thailand","text":"«Mein Mann stammt aus Hessen. Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche. Aber jetzt gehen unsere beiden Söhne zur Schule, und ich habe gemerkt, dass meine Deutschkenntnisse nicht mehr ausreichend sind: In der Kommunikation mit der Klassenlehrerin und bei Elternabenden habe ich grosse Schwierigkeiten. Deshalb nehme ich jetzt an einem Deutschkurs für Eltern teil.»"},{"label":"Abdullah, 35, aus Bahrain","text":"«Ich arbeite seit ein paar Monaten an einer deutschen Klinik als Arzt. Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen. Im Krankenhaus brauche ich eigentlich gar nicht so viel Deutsch, denn für die Gespräche mit den Patienten genügt mein Deutsch, und die Kollegen sprechen alle sehr gut Englisch. Aber natürlich möchte ich die Sprache des Landes gut können, in dem ich lebe. Dann versteht man die Menschen und ihr Land besser. Aus diesem Grund lerne ich weiter Deutsch.»"},{"label":"Zeliha, 45, aus der Türkei","text":"«Ich bin nach Dortmund gekommen, als ich meinen Mann – einen Deutschtürken – geheiratet habe. Schnell kamen vier Kinder zur Welt. Das Geld war immer knapp bei uns, deswegen habe ich neben dem Haushalt und der Kindererziehung Schicht gearbeitet. Für einen Deutschkurs war nie Zeit und Geld da. Meine Kinder haben oft geschimpft, weil ich so schlecht Deutsch sprach. Jetzt lerne ich endlich richtig Deutsch, und meine Kinder helfen mir beim Lernen.»"}],"items":[{"label":"a","lead":"Wer gut Englisch kann, … ○ findet in Deutschland problemlos einen Job. ○ muss trotzdem gut Deutsch lernen.","text":"Wer gut Englisch kann, ___.","gaps":[["muss trotzdem gut Deutsch lernen","muss trotzdem"]],"solution":"Wer gut Englisch kann, **muss trotzdem gut Deutsch lernen**.","en":"Kto dobrze zna angielski, i tak musi się dobrze nauczyć niemieckiego.","why":"Bradowi, dla którego angielski jest językiem ojczystym, w kółko powtarzano: *Lernen Sie erst einmal richtig Deutsch.*"},{"label":"b","lead":"Deutsche glauben offenbar, … ○ dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat. ○ dass man für eine Ausbildung Deutsch braucht.","text":"Deutsche glauben offenbar, ___.","gaps":[["dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat","dass man ohne perfektes Deutsch"]],"solution":"Deutsche glauben offenbar, **dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat**.","en":"Niemcy najwyraźniej uważają, że bez perfekcyjnego niemieckiego nie ma się kwalifikacji zawodowych.","why":"Brad: *… dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht.*"},{"label":"c","lead":"Alena hofft, dass sie mit dem Zertifikat Deutsch … ○ eine Arbeitsstelle in Österreich findet. ○ besser Bewerbungen schreiben kann.","text":"Alena hofft, dass sie mit dem Zertifikat Deutsch ___.","gaps":[["eine Arbeitsstelle in Österreich findet","eine Arbeitsstelle"]],"solution":"Alena hofft, dass sie mit dem Zertifikat Deutsch **eine Arbeitsstelle in Österreich findet**.","en":"Alena ma nadzieję, że z certyfikatem z niemieckiego (Zertifikat Deutsch) znajdzie pracę w Austrii.","why":"Alena liczy na dobre szanse *bei österreichischen Firmen*."},{"label":"d","lead":"Als Polin will Ewa Deutsch können, denn … ○ Deutschland und Polen haben eine gemeinsame Geschichte. ○ sie hat viele Deutsche kennengelernt.","text":"Als Polin will Ewa Deutsch können, denn ___.","gaps":[["Deutschland und Polen haben eine gemeinsame Geschichte","Deutschland und Polen"]],"solution":"Als Polin will Ewa Deutsch können, denn **Deutschland und Polen haben eine gemeinsame Geschichte**.","en":"Jako Polka Ewa chce znać niemiecki, bo Niemcy i Polska mają wspólną historię.","why":"Ewa: *Denn Polen und Deutschland verbindet eine lange Geschichte.*"},{"label":"e","lead":"Ewa findet es … ○ toll, dass so viel Deutsche Polnisch sprechen. ○ schade, dass sich nicht so viele Deutsche für Polnisch interessieren.","text":"Ewa findet es ___.","gaps":[["schade, dass sich nicht so viele Deutsche für Polnisch interessieren","schade"]],"solution":"Ewa findet es **schade, dass sich nicht so viele Deutsche für Polnisch interessieren**.","en":"Ewa żałuje, że niewielu Niemców interesuje się językiem polskim.","why":"Ewa chciałaby, żeby więcej Niemców interesowało się polskim."},{"label":"f","lead":"Sopha hat … ○ von ihrem Mann Deutsch gelernt. ○ hat einen Integrationskurs besucht.","text":"Sopha hat ___.","gaps":[["von ihrem Mann Deutsch gelernt","von ihrem Mann"]],"solution":"Sopha hat **von ihrem Mann Deutsch gelernt**.","en":"Sopha nauczyła się niemieckiego od męża.","why":"Sopha: *Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche.*"},{"label":"g","lead":"Sie … ○ muss ihren Söhnen bei den Deutschhausaufgaben helfen. ○ hat Probleme, weil sie die Lehrer nicht gut genug versteht.","text":"Sie ___.","gaps":[["hat Probleme, weil sie die Lehrer nicht gut genug versteht","hat Probleme"]],"solution":"Sie **hat Probleme, weil sie die Lehrer nicht gut genug versteht**.","en":"Ma problemy, bo nie rozumie wystarczająco dobrze nauczycieli.","why":"Z wychowawcą klasy i na zebraniach z rodzicami ma *grosse Schwierigkeiten*."},{"label":"h","lead":"Für die Arbeitserlaubnis … ○ werden gute Deutschkenntnisse erwartet. ○ braucht man gar nicht so gute Deutschkenntnisse.","text":"Für die Arbeitserlaubnis ___.","gaps":[["werden gute Deutschkenntnisse erwartet","werden gute"]],"solution":"Für die Arbeitserlaubnis **werden gute Deutschkenntnisse erwartet**.","en":"Do pozwolenia na pracę wymagana jest dobra znajomość niemieckiego.","why":"Abdullah: *Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen.*"},{"label":"i","lead":"Abdullah will gut Deutsch können, weil … ○ die Patienten nicht Englisch sprechen. ○ er in Deutschland lebt.","text":"Abdullah will gut Deutsch können, weil ___.","gaps":[["er in Deutschland lebt"]],"solution":"Abdullah will gut Deutsch können, weil **er in Deutschland lebt**.","en":"Abdullah chce dobrze znać niemiecki, bo mieszka w Niemczech.","why":"Chce znać język *des Landes …, in dem ich lebe*; jego niemiecki już wystarcza do rozmów z pacjentami."},{"label":"j","lead":"Zeliha lernt Deutsch … ○ , weil sie Geld verdienen muss. ○ wegen ihrer Kinder.","text":"Zeliha lernt Deutsch ___.","gaps":[["wegen ihrer Kinder"]],"solution":"Zeliha lernt Deutsch **wegen ihrer Kinder**.","en":"Zeliha uczy się niemieckiego ze względu na dzieci.","why":"Jej dzieci narzekały, że jej niemiecki jest taki słaby, a teraz pomagają jej się uczyć."}]}]},{"page":"Test L4 · 22","heading":"Sprechen","heading_en":"Mówienie","exercises":[{"no":"7","instruction":"Welche Reaktion passt am besten? Verbinden Sie.","instruction_en":"Która odpowiedź pasuje najlepiej? Po każdym zdaniu wpisz numer odpowiedzi (1–6). (Ćwiczenie 6 na tej stronie to zadanie ze słuchania i zostało pominięte.)","example":[{"label":"a","text":"Darf ich Sie kurz etwas fragen? → **2** Natürlich, gern."}],"items":[{"label":"b","text":"Mein Name ist Kranitzky-Krampe. → ___","gaps":[["5"]],"solution":"Mein Name ist Kranitzky-Krampe. → **5**","en":"Nazywam się Kranitzky-Krampe. → 5 Przepraszam, jak brzmi Pana nazwisko?","why":"Długie, nietypowe nazwisko: dopytujesz."},{"label":"c","text":"Zu Kleidung kann man auch «Klamotten» sagen. → ___","gaps":[["4"]],"solution":"Zu Kleidung kann man auch «Klamotten» sagen. → **4**","en":"Na ubrania można też powiedzieć „Klamotten”. → 4 Nigdy nie słyszałem tego słowa.","why":"Nowe (potoczne) słowo: *Das Wort habe ich noch nie gehört.*"},{"label":"d","text":"Was bedeutet dieses Wort? → ___","gaps":[["1"]],"solution":"Was bedeutet dieses Wort? → **1**","en":"Co znaczy to słowo? → 1 Niestety też nie wiem.","why":"Odpowiedź na pytanie, na które nie znasz odpowiedzi."},{"label":"e","text":"Da habe ich echt Schwein gehabt. → ___","gaps":[["6"]],"solution":"Da habe ich echt Schwein gehabt. → **6**","en":"Naprawdę miałem wtedy szczęście. → 6 Czy dobrze zrozumiałem: miał Pan szczęście?","why":"*Schwein haben* (potocznie) = mieć szczęście; sprawdzasz, czy dobrze zrozumiałeś."},{"label":"f","text":"Könnten Sie bitte langsamer sprechen? → ___","gaps":[["3"]],"solution":"Könnten Sie bitte langsamer sprechen? → **3**","en":"Czy mógłby Pan mówić trochę wolniej? → 3 Dobrze, postaram się.","why":"Odpowiedź na prośbę."}],"phrases":["1 Das weiss ich leider auch nicht.","2 Natürlich, gern.","3 Okay, ich versuche es.","4 Das Wort habe ich noch nie gehört.","5 Wie war bitte Ihr Name?","6 Habe ich das richtig verstanden: Du hattest Glück?"]},{"no":"8","instruction":"Schreiben Sie die Fragen.","instruction_en":"Napisz pytania zależne ze słowami w nawiasach. W pytaniu zależnym czasownik idzie na koniec.","example":[{"label":"a","lead":"(Bild: Ein Mann und eine Frau lesen zusammen in einem Buch.) Weisst du vielleicht, … (Aufgabe – wie?)","text":"Weisst du vielleicht, **wie ich diese Aufgaben machen muss**?"}],"items":[{"label":"b","lead":"(Bild: Zwei Männer stehen mit ihren Mülltonnen auf der Strasse.) Können Sie mir sagen, … (Müll – wohin?)","text":"Können Sie mir sagen, ___?","gaps":[["wohin ich den Müll bringen muss","wohin ich den Müll bringen soll"]],"solution":"Können Sie mir sagen, **wohin ich den Müll bringen muss**?","en":"Czy może mi Pan powiedzieć, dokąd mam zanieść śmieci?","why":"*wohin* zaczyna pytanie zależne; odmieniony czasownik *muss* idzie na koniec."},{"label":"c","lead":"(Bild: Eine Frau sitzt beim Arzt.) Können Sie mir bitte sagen, … (Schmerzen – wo?)","text":"Können Sie mir bitte sagen, ___?","gaps":[["wo Sie Schmerzen haben"]],"solution":"Können Sie mir bitte sagen, **wo Sie Schmerzen haben**?","en":"Czy może mi Pani powiedzieć, gdzie Panią boli?","why":"Pyta lekarz: *wo* + podmiot + czasownik na końcu (*haben*)."},{"label":"d","lead":"(Bild: Eine Frau fragt einen Mann im Zug.) Wissen Sie vielleicht, … (Zug nach Berlin – ob?)","text":"Wissen Sie vielleicht, ___?","gaps":[["ob der Zug nach Berlin fährt","ob dieser Zug nach Berlin fährt","ob das der Zug nach Berlin ist"]],"solution":"Wissen Sie vielleicht, **ob der Zug nach Berlin fährt**?","en":"Czy wie Pan może, czy ten pociąg jedzie do Berlina?","why":"Pytanie typu tak/nie staje się zależne z *ob*; czasownik *fährt* idzie na koniec."}]}]},{"page":"Test L4 · 23","heading":"Schreiben","heading_en":"Pisanie","exercises":[{"no":"9","instruction":"Wählen Sie eine Sprache, die Sie gern lernen würden, und schreiben Sie eine Nachricht an die Sprachschule. – Schreiben Sie, für welche Sprache Sie sich interessieren. – Sagen Sie, wann und wie oft pro Woche Sie Zeit für den Kurs haben. – Fragen Sie, zu welchen Terminen/Zeiten die Sprachschule einen Kurs in Ihrer Wunschsprache anbietet. – Fragen Sie auch nach den Kursgebühren und der Kursdauer. – Bitten Sie um eine Antwort. – Denken Sie an die passende Anrede und den Gruss am Ende.","instruction_en":"Wybierz język, którego chcesz się nauczyć, i napisz wiadomość do szkoły językowej: jaki język, kiedy i ile razy w tygodniu masz czas, w jakich terminach i godzinach są kursy, ile kosztuje kurs i jak długo trwa; poproś o odpowiedź i użyj odpowiedniego powitania i zakończenia. Przykładowa odpowiedź jest zgodna z oficjalnym kluczem.","phrases":["… Damen und Herren,","ich würde gern …","Ich … und …","Bitte teilen Sie mir mit, …","Auch müsste ich wissen, …","Mit …","**LERNTIPP** Was sagt man in dieser Situation? Notieren und lernen Sie nicht nur einzelne neue Wörter. Wenn Sie sich zu verschiedenen Situationen passende Sätze und Ausdrücke aufschreiben, fühlen Sie sich in Gesprächen sicherer. Benutzen Sie zum Beispiel Karteikärtchen und schreiben Sie eine Situation oder ein Thema auf die Vorderseite: «nachfragen». Schreiben Sie Beispiele zum Thema auf die Rückseite und lernen Sie diese auswendig: «Was meinen Sie mit …?», «Was bedeutet …?» … Diese Methode eignet sich auch gut, wenn Sie sich auf ein Gespräch vorbereiten möchten. Überlegen Sie, was Sie sagen oder fragen möchten und was der Gesprächspartner sagen oder fragen könnte. Sicher können Sie während des Gesprächs einen Ihrer geübten Sätze anwenden."],"items":[{"label":"9","text":"","open":true,"solution":"**Sehr geehrte** Damen und Herren, ich würde gern **Neugriechisch lernen**. Ich **habe von Montag bis Donnerstag abends Zeit** und **könnte zweimal pro Woche kommen**. Bitte teilen Sie mir mit, **zu welchen Zeiten Sie einen Neugriechisch-Kurs anbieten**. Auch müsste ich wissen, **wie viel der Kurs kostet und wie lange er dauert**. **Ich bitte Sie um eine kurze Antwort.** Mit **freundlichen Grüssen** …","en":"Szanowni Państwo, chciałbym nauczyć się nowogreckiego. Mam czas od poniedziałku do czwartku wieczorami i mógłbym przychodzić dwa razy w tygodniu. Proszę o informację, w jakich godzinach oferują Państwo kurs języka nowogreckiego. Musiałbym też wiedzieć, ile kosztuje kurs i jak długo trwa. Proszę o krótką odpowiedź. Z poważaniem …","why":"List formalny: *Sehr geehrte Damen und Herren* … *Mit freundlichen Grüssen*. Pytania są zależne (*zu welchen Zeiten …, wie viel …, wie lange …*): czasownik na końcu."}]}]}]},{"id":"04-zu-infinitiv-bewerbung","no":4,"title":"Infinitiv mit zu · Bewerbung · Test Lektion 5","title_en":"Bezokolicznik z zu, list motywacyjny, small talk o pracy · test z lekcji 5","added":"2026-11-12","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 5","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (oficjalny klucz odpowiedzi, Lektion 5)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g98","title":"grammis: Verben mit einem Infinitiv mit oder ohne zu (czasowniki modalne bez zu; brauchen z zu)","url":"https://grammis.ids-mannheim.de/fragen/98"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (zdania bezokolicznikowe z zu)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"g4069","title":"grammis: Verbflexion (zu między przedrostkiem a czasownikiem: anzurufen)","url":"https://grammis.ids-mannheim.de/progr@mm/4069"},{"id":"g6393","title":"grammis: Alternation von zu- und dass-Komplementen (zdanie z dass lub zu + bezokolicznik)","url":"https://grammis.ids-mannheim.de/korpusgrammatik/6393"},{"id":"g299310","title":"grammis: während (przyimek, z dopełniaczem)","url":"https://grammis.ids-mannheim.de/praepositionen/299310"},{"id":"prep","title":"grammis: Präpositionalphrase (przyimki i przypadki, których wymagają)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"}],"pages":[{"page":"AB 140","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Zacznij wreszcie pisać podania o pracę!","exercises":[{"no":"1","tag":"A1","instruction":"Ich habe leider keine Zeit …","instruction_en":"Niestety nie mam czasu …","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Uzupełnij każde zdanie czasownikiem z ramki. Każdy jest użyty raz; przekreślony jest użyty w przykładzie.","box":["mitzuarbeiten","auszuschalten","zu erklären","mitzukommen","zu sein","zu gehen"],"box_used":[5],"box_exact":true,"example":[{"label":"1","text":"Erlaubst du uns, ins Kino **zu gehen**?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd ___.","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, den Herd **auszuschalten**.","en":"Nie zapomnijcie, proszę, wyłączyć kuchenki.","why":"*ausschalten* jest rozdzielnie złożony, więc *zu* stoi między przedrostkiem a czasownikiem: *aus**zu**schalten*.","source":"g4069"},{"label":"3","text":"Ich habe Angst, nachts allein ___.","gaps":[["zu sein"]],"solution":"Ich habe Angst, nachts allein **zu sein**.","en":"Boję się być w nocy sam.","why":"*Angst haben* + *zu* + bezokolicznik; *sein* to czasownik prosty, więc *zu* stoi przed nim.","source":"g6865"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein ___.","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein **mitzuarbeiten**.","en":"Nie, działanie w klubie nie jest zbyt stresujące.","why":"*Es ist* + przymiotnik + *zu* + bezokolicznik. *mitarbeiten* jest rozdzielnie złożony: *mit**zu**arbeiten*. (Pierwsze *zu* znaczy tu „zbyt”.)","source":"g4069"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg ___.","gaps":[["zu erklären"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg **zu erklären**.","en":"Niestety nie mam czasu, żeby wytłumaczyć Panu drogę.","why":"*keine Zeit haben* + *zu* + bezokolicznik. *erklären* nie jest rozdzielnie złożony (*er-* to przedrostek nierozdzielny), więc *zu* stoi przed nim.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, ins Training ___.","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, ins Training **mitzukommen**.","en":"Nie mam dziś ochoty pójść z wami na trening.","why":"*keine Lust haben* + *zu* + bezokolicznik; *mitkommen* jest rozdzielnie złożony: *mit**zu**kommen*.","source":"g4069"}]},{"no":"1","part":"b","part_instruction":"Nach welchen Ausdrücken folgt *zu*? Markieren Sie in a wie im Beispiel.","part_instruction_en":"Po jakich wyrażeniach stoi *zu*? Wpisz wyrażenie (czasownik albo czasownik + rzeczownik/przymiotnik), po którym w każdym zdaniu z a pojawia się *zu*.","example":[{"label":"1","text":"**Erlaubst** du uns, ins Kino zu gehen?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd auszuschalten. → ___","gaps":[["Vergesst","Vergesst bitte nicht","vergessen","vergesst nicht"]],"solution":"Vergesst bitte nicht, den Herd auszuschalten. → **Vergesst**","en":"Nie zapomnijcie, proszę, wyłączyć kuchenki. → zapomnieć","why":"Po czasowniku *vergessen* (tu *Vergesst*) stoi *zu* + bezokolicznik.","source":"hueber"},{"label":"3","text":"Ich habe Angst, nachts allein zu sein. → ___","gaps":[["habe Angst","Angst haben","Ich habe Angst","Angst"]],"solution":"Ich habe Angst, nachts allein zu sein. → **habe Angst**","en":"Boję się być w nocy sam. → bać się","why":"Po *haben* + rzeczownik (*Angst, Lust, Zeit, Interesse*) stoi *zu* + bezokolicznik.","source":"hueber"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → ___","gaps":[["ist nicht zu stressig","es ist nicht zu stressig","ist stressig","stressig sein","es ist stressig","stressig"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → **ist nicht zu stressig**","en":"Nie, działanie w klubie nie jest zbyt stresujące. → (nie) jest zbyt stresujące","why":"Po *Es ist* + przymiotnik stoi *zu* + bezokolicznik.","source":"hueber"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → ___","gaps":[["habe leider keine Zeit","habe keine Zeit","keine Zeit haben","Zeit haben","keine Zeit","Zeit"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → **habe leider keine Zeit**","en":"Niestety nie mam czasu, żeby wytłumaczyć Panu drogę. → (nie) mieć czasu","why":"Po *Zeit haben* (tu *keine Zeit*) stoi *zu* + bezokolicznik.","source":"hueber"},{"label":"6","text":"Ich habe heute keine Lust, ins Training mitzukommen. → ___","gaps":[["habe heute keine Lust","habe keine Lust","keine Lust haben","Lust haben","keine Lust","Lust"]],"solution":"Ich habe heute keine Lust, ins Training mitzukommen. → **habe heute keine Lust**","en":"Nie mam dziś ochoty pójść z wami na trening. → (nie) mieć ochoty","why":"Po *Lust haben* (tu *keine Lust*) stoi *zu* + bezokolicznik.","source":"hueber"}]},{"no":"1","part":"c","part_instruction":"Wo steht *zu*? Ergänzen Sie die Tabelle mit den Sätzen aus a.","part_instruction_en":"Gdzie stoi *zu*? Tabela ma trzy kolumny: początek zdania, część środkową, potem czasownik z *zu*. Wstaw do niej zdania z a z czasownikiem rozdzielnie złożonym (2, 4, 6) i wpisz ostatnią kolumnę. Części czasownika są w nawiasach.","example":[{"label":"1","text":"Erlaubst du uns, | ins Kino | **zu gehen**? (gehen)"}],"items":[{"label":"2","text":"Vergesst bitte nicht, | den Herd | ___. (aus·schalten)","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, | den Herd | **auszuschalten**. (aus·schalten)","en":"Nie zapomnijcie, proszę, | kuchenki | wyłączyć.","why":"Czasownik rozdzielnie złożony: *zu* stoi między *aus* a *schalten* i całość pisze się jako jedno słowo.","source":"g4069"},{"label":"4","text":"Nein, es ist nicht zu stressig, | in einem Verein | ___. (mit·arbeiten)","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, | in einem Verein | **mitzuarbeiten**. (mit·arbeiten)","en":"Nie, nie jest zbyt stresujące | w klubie | działać.","why":"Czasownik rozdzielnie złożony: *mit* + *zu* + *arbeiten*, pisane jako jedno słowo.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, | ins Training | ___. (mit·kommen)","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, | ins Training | **mitzukommen**. (mit·kommen)","en":"Nie mam dziś ochoty | na trening | pójść z wami.","why":"Czasownik rozdzielnie złożony: *mit* + *zu* + *kommen*, pisane jako jedno słowo.","source":"g4069"}]},{"no":"2","tag":"A1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Co jest poprawne? Wpisz *zu*, jeśli zdanie potrzebuje *zu*, albo *–* (myślnik), jeśli niczego nie potrzebuje.","example":[{"label":"a","text":"Ich höre nicht auf, nach meinem Traumjob **zu** suchen."}],"items":[{"label":"b","text":"Möchten Sie nicht auch in Ihrem Traumberuf ___ arbeiten?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Möchten Sie nicht auch in Ihrem Traumberuf **–** arbeiten?","en":"Czy nie chciałby Pan też pracować w swoim wymarzonym zawodzie?","why":"Po czasowniku modalnym (*möchten*) bezokolicznik nigdy nie dostaje *zu*.","source":"g98"},{"label":"c","text":"Ich könnte mir gut vorstellen, ein Handwerk ___ lernen.","gaps":[["zu"]],"solution":"Ich könnte mir gut vorstellen, ein Handwerk **zu** lernen.","en":"Mógłbym sobie dobrze wyobrazić, że uczę się jakiegoś rzemiosła.","why":"*sich vorstellen können* wprowadza po przecinku drugą część zdania z *zu* + bezokolicznik. *könnte* należy tylko do *vorstellen*.","source":"g6865"},{"label":"d","text":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz ___ finden.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz **–** finden.","en":"Z wykształceniem rzemieślniczym można znaleźć dobrą pracę.","why":"Czasownik modalny *kann* + bezokolicznik bez *zu*.","source":"g98"},{"label":"e","text":"Könnten Sie mir bei der Berufswahl ___ helfen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Könnten Sie mir bei der Berufswahl **–** helfen?","en":"Czy mógłby mi Pan pomóc w wyborze zawodu?","why":"*Könnten* to czasownik modalny (Konjunktiv II od *können*): bez *zu*.","source":"g98"},{"label":"f","text":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten ___ informieren.","gaps":[["zu"]],"solution":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten **zu** informieren.","en":"Dowiadywanie się o możliwościach zawodowych jest dość stresujące.","why":"*Es ist* + przymiotnik (*stressig*) + *zu* + bezokolicznik.","source":"g6865"}]},{"no":"3","tag":"A1","marker":"◇","instruction":"Ergänzen Sie: *zu* oder *–*.","instruction_en":"Uzupełnij słowem *zu* albo wpisz *–* (myślnik) tam, gdzie niczego nie brakuje.","example":[{"label":"a","text":"Ich habe schon einmal angefangen, das Bewerbungsgespräch vor**zu**bereiten."}],"items":[{"label":"b","text":"Wir dürfen den Geburtstag der Chefin nicht ___ vergessen!","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Wir dürfen den Geburtstag der Chefin nicht **–** vergessen!","en":"Nie możemy zapomnieć o urodzinach szefowej!","why":"Czasownik modalny *dürfen* + bezokolicznik bez *zu*.","source":"g98"},{"label":"c","text":"Es ist nicht leicht, eine Stelle in seinem Traumjob ___ finden.","gaps":[["zu"]],"solution":"Es ist nicht leicht, eine Stelle in seinem Traumjob **zu** finden.","en":"Nie jest łatwo znaleźć posadę w wymarzonym zawodzie.","why":"*Es ist nicht leicht* + *zu* + bezokolicznik.","source":"g6865"},{"label":"d","text":"Ich würde am liebsten in einem Team ___ arbeiten.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Ich würde am liebsten in einem Team **–** arbeiten.","en":"Najchętniej pracowałbym w zespole.","why":"*würde* + bezokolicznik (Konjunktiv II) działa jak czasownik modalny: bez *zu*.","source":"g98"},{"label":"e","text":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung ___ helfen?","gaps":[["zu"]],"solution":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung **zu** helfen?","en":"Masz może chwilę, żeby pomóc mi przy podaniu o pracę?","why":"*Zeit haben* + *zu* + bezokolicznik.","source":"g6865"},{"label":"f","text":"Kannst du dir eine Lehre im Büro vor ___ stellen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Kannst du dir eine Lehre im Büro vor **–** stellen?","en":"Czy wyobrażasz sobie naukę zawodu w biurze?","why":"*Kannst* to czasownik modalny, więc nic nie wstawiasz: *vorstellen* pisze się jako jedno słowo.","source":"g98"}]}]},{"page":"AB 141","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Zacznij wreszcie pisać podania o pracę!","exercises":[{"no":"4","instruction":"Schreiben Sie Sätze.","instruction_en":"Napisz zdania o swoim życiu zawodowym: połącz wyrażenie z lewej ramki z czynnością z prawej ramki. Przekreślone słowa są użyte w przykładzie. Przykładowa odpowiedź to jedna z możliwości.","box":["(keine) Lust haben","möchten","hoffen","Freude machen","können","sich vorstellen können","würde … gern","anstrengend sein","…","ein halbes Jahr um die Welt reisen","am Abend arbeiten","(nicht) immer dasselbe machen","sehr gut selbstständig arbeiten","mit netten Kollegen zusammenarbeiten","Neues lernen","wenig Freizeit haben"],"box_used":[0,1,10],"example":[{"label":"Beispiel","text":"Ich habe keine Lust, am Abend **zu arbeiten**. Ich möchte in meinem Berufsleben …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich möchte in meinem Berufsleben nicht immer dasselbe machen. Ich hoffe, mit netten Kollegen zusammenzuarbeiten. Es macht mir Freude, Neues zu lernen. Ich kann sehr gut selbstständig arbeiten. Es ist anstrengend, wenig Freizeit zu haben. Ich würde gern ein halbes Jahr um die Welt reisen.","en":"W życiu zawodowym nie chciałbym robić ciągle tego samego. Mam nadzieję, że będę pracować z miłymi kolegami. Uczenie się nowych rzeczy sprawia mi radość. Potrafię bardzo dobrze pracować samodzielnie. Męczące jest mieć mało wolnego czasu. Chętnie podróżowałbym przez pół roku po świecie.","why":"Po *hoffen, Freude machen, sich vorstellen können, anstrengend sein, Lust haben* używaj *zu* + bezokolicznik (czasowniki rozdzielnie złożone: *zusammen**zu**arbeiten*). Po *möchten, können, würde … gern* bez *zu*.","source":"g98"}]},{"no":"5","instruction":"Ordnen Sie zu und schreiben Sie Sätze mit *zu*.","instruction_en":"Dopasuj każdą wypowiedź do czasownika z ramki i napisz zdanie z *zu* + bezokolicznik. Przekreślony czasownik jest użyty w przykładzie.","box":["sich vorstellen können","versuchen","aufhören","versprechen","vorhaben"],"box_used":[1],"example":[{"label":"a","lead":"Morgen will ich pünktlich sein. Vielleicht!","text":"versuchen: Morgen versuche ich, pünktlich **zu sein**."}],"items":[{"label":"b","lead":"Ich hole dich morgen ab. Ganz sicher.","text":"","accept":["Ich verspreche, dich morgen abzuholen.","Ich verspreche dir, dich morgen abzuholen.","versprechen: Ich verspreche, dich morgen abzuholen."],"solution":"**Ich verspreche, dich morgen abzuholen.**","en":"Obiecuję, że jutro cię odbiorę.","why":"„Na pewno” = obietnica: *versprechen*. *abholen* jest rozdzielnie złożony: *ab**zu**holen*.","source":"hueber"},{"label":"c","lead":"Einen interessanten Job finden! Das ist mein Plan.","text":"","accept":["Ich habe vor, einen interessanten Job zu finden.","vorhaben: Ich habe vor, einen interessanten Job zu finden."],"solution":"**Ich habe vor, einen interessanten Job zu finden.**","en":"Mam zamiar znaleźć ciekawą pracę.","why":"Plan = *vorhaben*: *Ich habe vor, … zu finden.* Przedrostek *vor* idzie na koniec zdania głównego.","source":"hueber"},{"label":"d","lead":"Ein Handwerk lernen? Ja, warum eigentlich nicht?","text":"","accept":["Ich kann mir vorstellen, ein Handwerk zu lernen.","Ich kann mir gut vorstellen, ein Handwerk zu lernen.","sich vorstellen können: Ich kann mir vorstellen, ein Handwerk zu lernen."],"solution":"**Ich kann mir vorstellen, ein Handwerk zu lernen.**","en":"Mogę sobie wyobrazić, że uczę się jakiegoś rzemiosła.","why":"„Czemu nie?” = potrafisz to sobie wyobrazić: *Ich kann mir vorstellen, … zu lernen.*","source":"hueber"},{"label":"e","lead":"Ich arbeite als Pflegefachmann. Aber nur noch bis Ende Monat.","text":"","accept":["Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.","Ende Monat höre ich auf, als Pflegefachmann zu arbeiten.","aufhören: Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten."],"solution":"**Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.**","en":"Pod koniec miesiąca przestaję pracować jako pielęgniarz.","why":"„Tylko do końca miesiąca” = przestać: *aufhören*, z *auf* na końcu zdania głównego, przed przecinkiem.","source":"hueber"}]},{"no":"6","instruction":"Markieren Sie noch neun Wörter und ordnen Sie zu.","instruction_en":"Znajdź w diagramie literowym dziewięć kolejnych słów i wstaw je do ogłoszeń o pracę A–C. Zakreślone słowa (*Bewerbung, Tätigkeit*) to przykłady. Wpisz każde słowo w formie, jakiej wymaga zdanie (rzeczowniki wielką literą).","reading":[{"label":"Buchstabengitter","text":"AUFGABENSGBESCHÄFTIGSTIBEWERBUNGTERWARTENZTÄTIGKEIT\nBEWERBUNGSUNTERLAGENZYTWHANDELUTPOÜKENNTNISSENKWAQ\nUNTERSTÜTZUNGMUSJÄMTILVORAUSSETZUNGDUQSCHRIFTLICHLW"},{"label":"A  Heimpflegedienst Bachmann","text":"Wir suchen für 15 Stunden pro Woche … (1) für den Patientenfahrdienst.\n… (2) für die Tätigkeit ist: + Führerausweis Kategorie B + … (3) in Erster Hilfe + Freude an der Arbeit mit Menschen\nEs … (4) Sie: + interessante … (5) + Weiterbildungsmöglichkeiten + ein angenehmes Betriebsklima\nBitte schicken Sie Ihre Bewerbung an personal@hpfd-bachmann.ch"},{"label":"B","text":"Detailhandelsassistent/in für unser kleines Modegeschäft gesucht!\nErfahrung im … (1) und Verkauf von Vorteil. Wenden Sie sich bei Fragen … (2) oder telefonisch an Frau Kleinert: kleinert@neuemode.ch / 031 330 110 10."},{"label":"C","text":"HAST DU HANDWERKLICHES TALENT?\n… (1) du dich gern mit Holz? Dann komm zu uns! Wir bieten dir eine Lehrstelle als Schreiner/in EFZ.\nSchick deine … (2) noch heute an: Clemens Meier (cl.meier@schreinerei-meier.ch)"}],"example":[{"label":"A","text":"… für die **Tätigkeit** ist: … Bitte schicken Sie Ihre **Bewerbung** an personal@hpfd-bachmann.ch"}],"items":[{"label":"A1","text":"Wir suchen für 15 Stunden pro Woche ___ für den Patientenfahrdienst.","gaps":[["Unterstützung"]],"solution":"Wir suchen für 15 Stunden pro Woche **Unterstützung** für den Patientenfahrdienst.","en":"Szukamy wsparcia do przewozu pacjentów na 15 godzin tygodniowo.","why":"*die Unterstützung* = wsparcie, pomoc; tu oznacza osobę, która pomaga.","source":"hueber"},{"label":"A2","text":"___ für die Tätigkeit ist: Führerausweis Kategorie B","gaps":[["Voraussetzung"]],"solution":"**Voraussetzung** für die Tätigkeit ist: Führerausweis Kategorie B","en":"Warunkiem podjęcia tej pracy jest: prawo jazdy kategorii B","why":"*die Voraussetzung* = wymaganie, warunek. *der Führerausweis* to szwajcarskie słowo na prawo jazdy.","source":"hueber"},{"label":"A3","text":"+ ___ in Erster Hilfe","gaps":[["Kenntnisse"]],"solution":"+ **Kenntnisse** in Erster Hilfe","en":"+ znajomość zasad pierwszej pomocy","why":"*Kenntnisse in* + celownik = znajomość czegoś / umiejętności w jakiejś dziedzinie.","source":"hueber"},{"label":"A4","text":"Es ___ Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","gaps":[["erwarten"]],"solution":"Es **erwarten** Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","en":"Na Pana / Panią czekają: ciekawe zadania, możliwości dokształcania, przyjemna atmosfera w pracy","why":"*Es erwarten Sie …* = „czekają na Pana / Panią …”; *es* zajmuje tylko pierwsze miejsce, a czasownik zgadza się z podmiotem w liczbie mnogiej, który stoi dalej.","source":"hueber"},{"label":"A5","text":"+ interessante ___","gaps":[["Aufgaben"]],"solution":"+ interessante **Aufgaben**","en":"+ ciekawe zadania","why":"*die Aufgabe, die Aufgaben* = zadanie, zadania; *interessante* pokazuje liczbę mnogą.","source":"hueber"},{"label":"B1","text":"Erfahrung im ___ und Verkauf von Vorteil.","gaps":[["Handel"]],"solution":"Erfahrung im **Handel** und Verkauf von Vorteil.","en":"Doświadczenie w handlu i sprzedaży będzie atutem.","why":"*der Handel* = handel, sprzedaż detaliczna; *im* = *in dem*. *von Vorteil* = atut, zaleta.","source":"hueber"},{"label":"B2","text":"Wenden Sie sich bei Fragen ___ oder telefonisch an Frau Kleinert.","gaps":[["schriftlich"]],"solution":"Wenden Sie sich bei Fragen **schriftlich** oder telefonisch an Frau Kleinert.","en":"W razie pytań prosimy zwrócić się pisemnie lub telefonicznie do pani Kleinert.","why":"*schriftlich oder telefonisch* = pisemnie lub telefonicznie.","source":"hueber"},{"label":"C1","text":"___ du dich gern mit Holz?","gaps":[["Beschäftigst"]],"solution":"**Beschäftigst** du dich gern mit Holz?","en":"Lubisz pracować z drewnem?","why":"*sich beschäftigen mit* = zajmować się czymś; *du beschäftigst dich*. To słowo zaczyna pytanie tak/nie, więc pisze się je wielką literą.","source":"hueber"},{"label":"C2","text":"Schick deine ___ noch heute an: Clemens Meier","gaps":[["Bewerbungsunterlagen"]],"solution":"Schick deine **Bewerbungsunterlagen** noch heute an: Clemens Meier","en":"Wyślij swoje dokumenty aplikacyjne jeszcze dziś do: Clemens Meier","why":"*die Bewerbungsunterlagen* (liczba mnoga) = CV, świadectwa i list razem.","source":"hueber"}]}]},{"page":"AB 142","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Zacznij wreszcie pisać podania o pracę!","exercises":[{"no":"7","tag":"A2","instruction":"Ergänzen Sie in der richtigen Form: *brauchen – müssen*.","instruction_en":"Uzupełnij właściwą formą *brauchen* lub *müssen*. Wskazówka: *brauchen* łączy się z *zu* + bezokolicznik oraz z przeczeniem albo z *nur*; *müssen* nigdy nie łączy się z *zu*.","example":[{"label":"a","text":"Ich **brauche** nur die neuen Wörter zu lernen, dann schaffe ich die Prüfung schon."}],"items":[{"label":"b","text":"Dein Zeugnis ist doch so gut. Du ___ dir wirklich keine Gedanken um einen Job zu machen.","gaps":[["brauchst"]],"solution":"Dein Zeugnis ist doch so gut. Du **brauchst** dir wirklich keine Gedanken um einen Job zu machen.","en":"Twoje świadectwo jest przecież takie dobre. Naprawdę nie musisz się martwić o pracę.","why":"Przeczenie (*keine*) + *zu machen*: *brauchen … zu* = *nicht müssen*.","source":"g98"},{"label":"c","text":"Wenn sie nur Teilzeit arbeitet, dann ___ sie nicht den ganzen Tag am Computer sitzen.","gaps":[["muss"]],"solution":"Wenn sie nur Teilzeit arbeitet, dann **muss** sie nicht den ganzen Tag am Computer sitzen.","en":"Jeśli pracuje tylko na część etatu, to nie musi cały dzień siedzieć przy komputerze.","why":"Bezokolicznik *sitzen* nie ma *zu*, więc czasownik to *müssen*: *sie muss … sitzen*.","source":"g98"},{"label":"d","text":"Wenn wir für drei Monate ins Ausland reisen wollen, dann ___ wir jetzt viel Geld sparen.","gaps":[["müssen"]],"solution":"Wenn wir für drei Monate ins Ausland reisen wollen, dann **müssen** wir jetzt viel Geld sparen.","en":"Jeśli chcemy wyjechać na trzy miesiące za granicę, to musimy teraz dużo oszczędzać.","why":"Bez *zu* i bez przeczenia: to obowiązek, więc *müssen*.","source":"g98"}]},{"no":"8","tag":"A2","instruction":"Mein Traumjob. Schreiben Sie Sätze mit *brauchen … zu*.","instruction_en":"Moja wymarzona praca. Napisz zdania z *brauchen … zu* + bezokolicznik (= nie musieć / musieć tylko).","example":[{"label":"a","lead":"(nicht früh aufstehen)","text":"In meinem Traumjob **brauche ich nicht früh aufzustehen**."}],"items":[{"label":"b","lead":"(keine langweiligen Aufgaben übernehmen)","text":"","accept":["Ich brauche keine langweiligen Aufgaben zu übernehmen.","In meinem Traumjob brauche ich keine langweiligen Aufgaben zu übernehmen."],"solution":"**Ich brauche keine langweiligen Aufgaben zu übernehmen.**","en":"Nie muszę wykonywać nudnych zadań.","why":"*brauchen* na drugim miejscu, *zu übernehmen* na końcu. *übernehmen* nie jest tu rozdzielnie złożony, więc *zu* stoi przed nim.","source":"g98"},{"label":"c","lead":"(keine Überstunden machen)","text":"","accept":["Ich brauche keine Überstunden zu machen.","In meinem Traumjob brauche ich keine Überstunden zu machen."],"solution":"**Ich brauche keine Überstunden zu machen.**","en":"Nie muszę robić nadgodzin.","why":"*keine* + *brauchen … zu* = brak obowiązku.","source":"g98"},{"label":"d","lead":"(nur arbeiten, wenn ich Lust dazu habe)","text":"","accept":["Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.","In meinem Traumjob brauche ich nur zu arbeiten, wenn ich Lust dazu habe."],"solution":"**Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.**","en":"Muszę pracować tylko wtedy, kiedy mam na to ochotę.","why":"*nur brauchen … zu* = musieć tylko. *zu arbeiten* zamyka zdanie główne przed zdaniem z *wenn*.","source":"g98"},{"label":"e","lead":"(nicht mit unfreundlichen Kollegen zusammenarbeiten)","text":"","accept":["Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.","In meinem Traumjob brauche ich nicht mit unfreundlichen Kollegen zusammenzuarbeiten."],"solution":"**Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.**","en":"Nie muszę współpracować z niemiłymi kolegami.","why":"*zusammenarbeiten* jest rozdzielnie złożony: *zusammen**zu**arbeiten*, jedno słowo.","source":"g4069"}]},{"no":"9","tag":"A4","instruction":"Ein Bewerbungsschreiben","instruction_en":"List motywacyjny","part":"a","part_instruction":"Lesen Sie und ordnen Sie.","part_instruction_en":"Przeczytaj części listu i ułóż je we właściwej kolejności: wpisz numer (1–8) każdej części. Części są tu oznaczone literami A–H w kolejności, w jakiej drukuje je książka; B to przykład.","example":[{"label":"B","text":"Bewerbung als Verkäufer von E-Bikes → **1**"}],"items":[{"label":"A","text":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → ___","gaps":[["5"]],"solution":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → **5**","en":"Łatwo przychodzi mi uczenie się nowych rzeczy. Poza tym lubię doradzać klientom. Dlatego chętnie pracowałbym u Państwa jako sprzedawca. → 5","why":"To, dlaczego chcesz tę pracę, pojawia się po doświadczeniu (4), a przed końcową prośbą (6).","source":"hueber"},{"label":"C","text":"Freundliche Grüsse / Tibor Kelemen → ___","gaps":[["7"]],"solution":"Freundliche Grüsse / Tibor Kelemen → **7**","en":"Z poważaniem / Tibor Kelemen → 7","why":"Pozdrowienie końcowe i twoje imię i nazwisko stoją po ostatnim zdaniu.","source":"hueber"},{"label":"D","text":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → ___","gaps":[["3"]],"solution":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → **3**","en":"Z dużym zainteresowaniem przeczytałem Państwa ogłoszenie i ubiegam się o wolne stanowisko sprzedawcy rowerów elektrycznych. → 3","why":"Pierwsze zdanie po powitaniu mówi, o jaką pracę się ubiegasz.","source":"hueber"},{"label":"E","text":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → ___","gaps":[["6"]],"solution":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → **6**","en":"Byłbym wdzięczny za zaproszenie na rozmowę kwalifikacyjną. → 6","why":"Standardowe ostatnie zdanie listu motywacyjnego.","source":"hueber"},{"label":"F","text":"Beilagen: Lebenslauf, Arbeitszeugnisse → ___","gaps":[["8"]],"solution":"Beilagen: Lebenslauf, Arbeitszeugnisse → **8**","en":"Załączniki: CV, świadectwa pracy → 8","why":"*Beilagen* (załączniki) są na samym końcu, pod nazwiskiem.","source":"hueber"},{"label":"G","text":"Sehr geehrte Damen und Herren → ___","gaps":[["2"]],"solution":"Sehr geehrte Damen und Herren → **2**","en":"Szanowni Państwo → 2","why":"Powitanie stoi po temacie listu. W Szwajcarii nie stawia się po nim przecinka.","source":"hueber"},{"label":"H","text":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → ___","gaps":[["4"]],"solution":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → **4**","en":"Jak wynika z moich dokumentów, po ukończeniu szkoły średniej (Sekundarschule) odbyłem naukę zawodu mechanika rowerowego w firmie „Velo-XL”. Potem przez dwa lata pracowałem jako pracownik w sklepie rowerowym i zdobyłem też pierwsze doświadczenia w sprzedaży. → 4","why":"Twoje wykształcenie i doświadczenie są po zdaniu otwierającym.","source":"hueber"}]}]},{"page":"AB 143","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Zacznij wreszcie pisać podania o pracę!","exercises":[{"no":"9","part":"b","part_instruction":"Ergänzen Sie das Bewerbungsschreiben. Hilfe finden Sie in a.","part_instruction_en":"Uzupełnij list motywacyjny. Pomoc znajdziesz w a.","reading":[{"label":"Lerntipp","text":"Ein Bewerbungsschreiben muss fehlerfrei sein! Notieren Sie zuerst Ihre typischen Fehler. Überprüfen Sie dann Ihren Text pro Fehlertyp einmal. Lassen Sie Ihre Bewerbung am Ende noch einmal von einem Muttersprachler Korrektur lesen."}],"example":[{"label":"1","text":"Bewerbung **als** Physiotherapeutin im Altersheim"}],"items":[{"label":"2","text":"Sehr ___ Frau Zerlich","gaps":[["geehrte"]],"solution":"Sehr **geehrte** Frau Zerlich","en":"Szanowna Pani","why":"*Sehr geehrte Frau …*, *Sehr geehrter Herr …*: końcówka zależy od osoby.","source":"hueber"},{"label":"3","text":"___ habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","gaps":[["Mit grossem Interesse"]],"solution":"**Mit grossem Interesse** habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","en":"Z dużym zainteresowaniem przeczytałam Państwa ogłoszenie o pracę i ubiegam się o stanowisko fizjoterapeutki.","why":"Stały zwrot otwierający z a; zajmuje pierwsze miejsce, więc zaraz po nim stoi czasownik *habe*.","source":"hueber"},{"label":"4","text":"Wie Sie ___ entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","gaps":[["meinen Unterlagen"]],"solution":"Wie Sie **meinen Unterlagen** entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","en":"Jak wynika z moich dokumentów, po szkole fizjoterapii pracowałam w Polsce przez cztery lata w szpitalu w Łodzi.","why":"*etwas (Dativ) entnehmen* = dowiedzieć się czegoś z czegoś: *meinen Unterlagen* to celownik liczby mnogiej.","source":"hueber"},{"label":"5","text":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch ___ im Bereich der Sportmedizin sammeln.","gaps":[["Erfahrungen","erste Erfahrungen"]],"solution":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch **Erfahrungen** im Bereich der Sportmedizin sammeln.","en":"Następnie przez dwa lata pracowałam w gabinecie Kunz & Rosenthal. Tam mogłam też zdobyć doświadczenie w dziedzinie medycyny sportowej.","why":"*Erfahrungen sammeln* = zdobywać doświadczenie.","source":"hueber"},{"label":"6","text":"___ ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","gaps":[["Meine Muttersprache"]],"solution":"**Meine Muttersprache** ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","en":"Moim językiem ojczystym jest polski. Ale mówię też bardzo dobrze po niemiecku i po angielsku.","why":"*die Muttersprache* = język ojczysty; *meine*, bo to rzeczownik rodzaju żeńskiego.","source":"hueber"},{"label":"7","text":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es ___ grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","gaps":[["macht mir"]],"solution":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es **macht mir** grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","en":"Praca w domu opieki to dla mnie coś zupełnie nowego. Uczenie się nowych rzeczy sprawia mi dużą radość. Poza tym lubię troszczyć się o innych ludzi i cieszę się na kontakt z mieszkańcami.","why":"*Es macht mir Freude, … zu* + bezokolicznik, jak w a.","source":"hueber"},{"label":"8","text":"Über eine Einladung ___ würde ich mich freuen.","gaps":[["zu einem persönlichen Gespräch"]],"solution":"Über eine Einladung **zu einem persönlichen Gespräch** würde ich mich freuen.","en":"Byłabym wdzięczna za zaproszenie na rozmowę kwalifikacyjną.","why":"Stałe zdanie końcowe: *eine Einladung zu* + celownik.","source":"hueber"},{"label":"9","text":"___ Alina Jankowska","gaps":[["Freundliche Grüsse"]],"solution":"**Freundliche Grüsse** Alina Jankowska","en":"Z poważaniem Alina Jankowska","why":"Pozdrowienie końcowe; szwajcarska pisownia *Grüsse*.","source":"hueber"}]},{"no":"9","part":"c","part_instruction":"Wählen Sie ein Stelleninserat und schreiben Sie eine Bewerbung.","part_instruction_en":"Wybierz jedno z trzech ogłoszeń o pracę z cyrku Tortellini (Zirkus Tortellini) i napisz list motywacyjny. Wykorzystaj części z a i b. Przykładowa odpowiedź to jedna z możliwości.","reading":[{"label":"1","text":"Zirkus Tortellini sucht Dompteur/-in\nWir erwarten: + Ausbildung als Tierpfleger/-in + Erfahrung mit wilden Tieren (Tiger, …)\nInfos und Bewerbung bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"2","text":"Sind Sie ein fröhlicher, positiver Mensch? Dann arbeiten Sie bei uns als Clown/-in\nSie haben Berufserfahrung als Kleinkinderzieher/-in oder als Schauspieler/-in? Sie können gut mit Kindern umgehen und haben viele lustige Ideen? Dann sind Sie die Richtige oder der Richtige für uns!\nGleich bewerben bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"3","text":"Wir suchen zwei Artisten für unseren Zirkus.\nSie haben: + eine Ausbildung als Tänzer/-in + erste Berufserfahrung an einem Theater gesammelt oder schon als Artist/-in in einem Zirkus gearbeitet\nSenden Sie Ihre Bewerbung an Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"}],"example":[{"label":"Beispiel","text":"Sehr geehrter Herr Tortellini / Mit grossem Interesse …"}],"items":[{"label":"1","lead":"Inserat 3: Artist/-in","text":"","open":true,"solution":"Bewerbung als Artistin / Sehr geehrter Herr Tortellini / Mit grossem Interesse habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Artistin in Ihrem Zirkus. Wie Sie meinen Unterlagen entnehmen können, habe ich eine Ausbildung als Tänzerin gemacht. Danach habe ich drei Jahre an einem Theater in Bern getanzt und dort erste Erfahrungen auf der Bühne gesammelt. Es macht mir grosse Freude, vor Publikum aufzutreten. Ich kann mir gut vorstellen, mit Ihrem Zirkus durch die Schweiz zu reisen. Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. / Freundliche Grüsse / Lara Steiner / Beilagen: Lebenslauf, Arbeitszeugnis","en":"Podanie o pracę na stanowisko akrobatki / Szanowny Panie / Z dużym zainteresowaniem przeczytałam Pana ogłoszenie o pracę i ubiegam się o stanowisko akrobatki w Pana cyrku. Jak wynika z moich dokumentów, ukończyłam szkołę tańca. Następnie przez trzy lata tańczyłam w teatrze w Bernie i zdobyłam tam pierwsze doświadczenia na scenie. Występowanie przed publicznością sprawia mi dużą radość. Dobrze mogę sobie wyobrazić podróżowanie z Pana cyrkiem po Szwajcarii. Byłabym wdzięczna za zaproszenie na rozmowę kwalifikacyjną. / Z poważaniem / Lara Steiner / Załączniki: CV, świadectwo pracy","why":"Te same osiem części co w a; każda odpowiada na jeden punkt ogłoszenia (wykształcenie tancerki, pierwsze doświadczenia w teatrze). *auf**zu**treten*: *auftreten* jest rozdzielnie złożony.","source":"g4069"}]}]},{"page":"AB 144","heading":"B  Während seines letzten Schuljahres …","heading_en":"W ostatnim roku szkoły …","exercises":[{"no":"10","tag":"B1","instruction":"Ergänzen Sie in der richtigen Form: *während – innerhalb – ausserhalb*.","instruction_en":"Uzupełnij słowem *während* (podczas), *innerhalb* (w ciągu) lub *ausserhalb* (poza) oraz słowem z nawiasu we właściwej formie. Wszystkie trzy łączą się z dopełniaczem.","example":[{"label":"a","text":"Man sollte schon **während der** (die) Schulzeit Schnupperlehren machen."}],"items":[{"label":"b","lead":"(wenige)","text":"Vielen Dank für Ihre Bewerbung. Sie erhalten ___ Wochen unsere Antwort.","gaps":[["innerhalb weniger"]],"solution":"Vielen Dank für Ihre Bewerbung. Sie erhalten **innerhalb weniger** Wochen unsere Antwort.","en":"Dziękujemy za Pana zgłoszenie. Odpowiedź otrzyma Pan w ciągu kilku tygodni.","why":"Granica czasowa = *innerhalb*; dopełniacz liczby mnogiej bez rodzajnika: *weniger Wochen*.","source":"prep"},{"label":"c","lead":"(unsere)","text":"Sie rufen ___ Geschäftszeiten an. Diese sind von …","gaps":[["ausserhalb unserer"]],"solution":"Sie rufen **ausserhalb unserer** Geschäftszeiten an. Diese sind von …","en":"Dzwonią Państwo poza naszymi godzinami pracy. Są one od …","why":"Poza jakimś przedziałem czasu = *ausserhalb*; dopełniacz liczby mnogiej *unserer Geschäftszeiten*.","source":"prep"},{"label":"d","lead":"(die)","text":"Sie können sich ___ Wartezeit gern einen Kaffee nehmen.","gaps":[["während der"]],"solution":"Sie können sich **während der** Wartezeit gern einen Kaffee nehmen.","en":"W czasie oczekiwania może się Pan śmiało poczęstować kawą.","why":"W tym samym czasie co = *während*; dopełniacz rodzaju żeńskiego *der Wartezeit*.","source":"g299310"},{"label":"e","lead":"(die)","text":"Die Firma möchte ihre Ergebnisse ___ nächsten zwei Jahre um 20 % verbessern.","gaps":[["innerhalb der"]],"solution":"Die Firma möchte ihre Ergebnisse **innerhalb der** nächsten zwei Jahre um 20 % verbessern.","en":"Firma chce w ciągu najbliższych dwóch lat poprawić swoje wyniki o 20%.","why":"Granica czasowa = *innerhalb*; dopełniacz liczby mnogiej *der nächsten zwei Jahre*.","source":"prep"}]},{"no":"11","tag":"B2","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij wywiad przyimkami czasu z ramki. Każdy jest użyty raz; *während* jest w ramce dwa razy. Przekreślone *von … an* jest użyte w przykładzie.","phrases":["ausserhalb","bei","von … bis","nach","von … an (Beispiel)","Vor","während","während"],"reading":[{"label":"Karrierestart","text":"Technikerin HF Maschinenbau – ein Beruf auch für Mädchen? Interview mit Samira\nKarrierestart: Warum machst du eine Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie lange dauert die Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie sieht dein Arbeitstag aus?\nKarrierestart: Welche Erfahrungen hast du als Frau … deiner Arbeit gemacht?"}],"example":[{"label":"d","text":"Ich durfte **von** Anfang **an** selbstständig Probleme lösen."}],"items":[{"label":"a","text":"Technik hat mich schon immer interessiert. Schon ___ meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","gaps":[["während"]],"solution":"Technik hat mich schon immer interessiert. Schon **während** meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","en":"Technika zawsze mnie interesowała. Już w czasie szkoły pracowałam u elektryka.","why":"*während* + dopełniacz (*meiner Schulzeit*) = podczas.","source":"g299310"},{"label":"b","text":"Gleich ___ der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","gaps":[["nach"]],"solution":"Gleich **nach** der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","en":"Zaraz po szkole odbyłam praktykę w dużym przedsiębiorstwie energetycznym.","why":"*nach* + celownik (*der Schule*) = po.","source":"prep"},{"label":"c","text":"Aber schon ___ des ersten Jahres lernt man die wichtigsten Dinge kennen.","gaps":[["während"]],"solution":"Aber schon **während** des ersten Jahres lernt man die wichtigsten Dinge kennen.","en":"Ale już podczas pierwszego roku poznaje się najważniejsze rzeczy.","why":"*während* + dopełniacz *des ersten Jahres*.","source":"g299310"},{"label":"e","text":"___ der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","gaps":[["Vor"]],"solution":"**Vor** der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","en":"Przed egzaminem końcowym muszę jednak jeszcze dużo się nauczyć.","why":"*vor* + celownik (*der Abschlussprüfung*) = przed; wielka litera na początku zdania.","source":"prep"},{"label":"f","text":"Ich bin ___ morgens ___ zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","gaps":[["von"],["bis"]],"solution":"Ich bin **von** morgens **bis** zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","en":"Od rana do końca dnia pracy jeżdżę po terenie naszego przedsiębiorstwa i naprawiam urządzenia.","why":"*von … bis* = od … do; *bis zum Feierabend* (*zum* = *zu dem*).","source":"prep"},{"label":"g","text":"Welche Erfahrungen hast du als Frau ___ deiner Arbeit gemacht?","gaps":[["bei"]],"solution":"Welche Erfahrungen hast du als Frau **bei** deiner Arbeit gemacht?","en":"Jakie doświadczenia masz jako kobieta w swojej pracy?","why":"*bei* + celownik (*deiner Arbeit*) = w trakcie, przy.","source":"prep"},{"label":"h","text":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also ___ der Arbeitszeit.","gaps":[["ausserhalb"]],"solution":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also **ausserhalb** der Arbeitszeit.","en":"Tylko pozytywne! Z kolegami często spotykamy się wieczorami, czyli poza godzinami pracy.","why":"*ausserhalb* + dopełniacz (*der Arbeitszeit*) = poza.","source":"prep"}]},{"no":"12","tag":"B2","instruction":"Lesen Sie den Text und schliessen Sie die Lücken 1–6. Welche Lösung (a, b oder c) passt am besten?","instruction_en":"Ćwiczenie egzaminacyjne: przeczytaj e-mail i uzupełnij luki 1–6. Która opcja (a, b lub c) pasuje najlepiej? Wpisz słowo (albo jego literę).","reading":[{"label":"E-Mail senden","text":"Sehr (0) Herr Nemati\nVielen Dank (1) Ihre Bewerbung als Automobil-Mechatroniker. Wir freuen uns über Ihr (2) an unserer Firma und laden Sie zu einem Vorstellungsgespräch am 25. Mai um 11.30 Uhr ein. Bitte geben Sie uns (3) der nächsten Tage Bescheid, (4) Sie zu diesem Termin kommen können. Bringen Sie noch folgende (5) mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat. Für Fragen und weitere Informationen (6) wir Ihnen gern zur Verfügung.\nFreundliche Grüsse\nFranziska Leumann – Garage Leumann"}],"example":[{"label":"0","lead":"a geehrter · b lieber · c freundlicher","text":"Sehr **geehrter** Herr Nemati"}],"items":[{"label":"1","lead":"a um · b für · c bei","text":"Vielen Dank ___ Ihre Bewerbung als Automobil-Mechatroniker.","gaps":[["für","b","b für"]],"solution":"Vielen Dank **für** Ihre Bewerbung als Automobil-Mechatroniker.","en":"Dziękujemy za Pana zgłoszenie na stanowisko mechatronika samochodowego.","why":"*Vielen Dank für* + biernik.","source":"hueber"},{"label":"2","lead":"a Bewerbung · b Interesse · c Mitarbeit","text":"Wir freuen uns über Ihr ___ an unserer Firma …","gaps":[["Interesse","b","b Interesse"]],"solution":"Wir freuen uns über Ihr **Interesse** an unserer Firma …","en":"Cieszymy się z Pana zainteresowania naszą firmą …","why":"*Interesse an* + celownik = zainteresowanie czymś; *Ihr* pasuje do rodzaju nijakiego *das Interesse*.","source":"hueber"},{"label":"3","lead":"a innerhalb · b ausserhalb · c bis","text":"Bitte geben Sie uns ___ der nächsten Tage Bescheid, …","gaps":[["innerhalb","a","a innerhalb"]],"solution":"Bitte geben Sie uns **innerhalb** der nächsten Tage Bescheid, …","en":"Prosimy dać nam znać w ciągu najbliższych dni, …","why":"Granica czasowa z dopełniaczem (*der nächsten Tage*) = *innerhalb*. *bis* wymagałoby *bis zum …*.","source":"prep"},{"label":"4","lead":"a wenn · b wann · c ob","text":"…, ___ Sie zu diesem Termin kommen können.","gaps":[["ob","c","c ob"]],"solution":"…, **ob** Sie zu diesem Termin kommen können.","en":"…, czy może Pan przyjść w tym terminie.","why":"Pytanie zależne typu tak/nie wymaga *ob* (czy).","source":"hueber"},{"label":"5","lead":"a Zeugnisse · b Sachen · c Dokumente","text":"Bringen Sie noch folgende ___ mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","gaps":[["Dokumente","c","c Dokumente"]],"solution":"Bringen Sie noch folgende **Dokumente** mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","en":"Prosimy przynieść również następujące dokumenty: oryginał świadectwa ukończenia szkoły zawodowej i Pana certyfikat B2.","why":"Świadectwo i dyplom to *Dokumente*; *Zeugnisse* nie obejmowałoby też certyfikatu B2, a *Sachen* jest zbyt ogólne jak na oficjalny list.","source":"hueber"},{"label":"6","lead":"a stellen · b stehen · c haben","text":"Für Fragen und weitere Informationen ___ wir Ihnen gern zur Verfügung.","gaps":[["stehen","b","b stehen"]],"solution":"Für Fragen und weitere Informationen **stehen** wir Ihnen gern zur Verfügung.","en":"W razie pytań i w sprawie dalszych informacji chętnie pozostajemy do Pana dyspozycji.","why":"Stały zwrot: *jemandem zur Verfügung stehen* = być do czyjejś dyspozycji.","source":"hueber"}]}]},{"page":"AB 145","heading":"B  Während seines letzten Schuljahres …","heading_en":"W ostatnim roku szkoły …","exercises":[{"no":"14","tag":"B3","instruction":"Verbinden Sie.","instruction_en":"Dopasuj każde pytanie lub uwagę z rozmowy kwalifikacyjnej do odpowiedzi (1–7). Wpisz numer. (Ćwiczenie 13 to zadanie ze słuchania i zostało pominięte.)","phrases":["1 Ich war zuständig für die Kontrolle von Haushalts-, Garten- und Freizeitartikeln.","2 Ich beherrsche die üblichen Programme und habe mich letztes Jahr im Bereich Lagerdatenbank weitergebildet.","3 Ja, ich würde gern wissen, wie gross das Lager hier ist.","4 Vielen Dank auch Ihnen.","5 Vielen Dank.","6 Ja, ich spreche drei Sprachen.","7 Also, ich bin Baumaschinenmechaniker und mache gerade den Führerausweis Kategorie BE."],"example":[{"label":"a","text":"Guten Tag, Herr Trantow. Nehmen Sie doch bitte Platz. → **5** Vielen Dank."}],"items":[{"label":"b","text":"Erzählen Sie doch bitte etwas über sich. → ___","gaps":[["7"]],"solution":"Erzählen Sie doch bitte etwas über sich. → **7**","en":"Proszę nam coś o sobie opowiedzieć. → 7 No więc jestem mechanikiem maszyn budowlanych i robię prawo jazdy kategorii BE.","why":"Przedstawiasz się: twój zawód i to, co teraz robisz.","source":"hueber"},{"label":"c","text":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → ___","gaps":[["1"]],"solution":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → **1**","en":"Jakie zadania miał Pan u swojego ostatniego pracodawcy? → 1 Odpowiadałem za kontrolę artykułów gospodarstwa domowego, ogrodowych i rekreacyjnych.","why":"*zuständig sein für* = odpowiadać za coś (twoje zadania).","source":"hueber"},{"label":"d","text":"Haben Sie noch andere Fähigkeiten? → ___","gaps":[["6"]],"solution":"Haben Sie noch andere Fähigkeiten? → **6**","en":"Czy ma Pan jeszcze inne umiejętności? → 6 Tak, mówię w trzech językach.","why":"Pytanie tak/nie o umiejętności: *Ja, …*","source":"hueber"},{"label":"e","text":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → ___","gaps":[["2"]],"solution":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → **2**","en":"Czy może mi Pan powiedzieć więcej o swoich umiejętnościach komputerowych? → 2 Znam popularne programy, a w zeszłym roku zrobiłem kurs doszkalający z magazynowych baz danych.","why":"*beherrschen* = opanować, biegle znać; *sich weiterbilden* = dokształcać się.","source":"hueber"},{"label":"f","text":"Haben Sie noch eine Frage? → ___","gaps":[["3"]],"solution":"Haben Sie noch eine Frage? → **3**","en":"Czy ma Pan jeszcze jakieś pytanie? → 3 Tak, chciałbym wiedzieć, jak duży jest tutaj magazyn.","why":"Pytanie zależne: *wie gross das Lager hier ist* (czasownik na końcu).","source":"hueber"},{"label":"g","text":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → ___","gaps":[["4"]],"solution":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → **4**","en":"Dziękujemy bardzo, że Pan do nas przyszedł, panie Trantow. → 4 Ja również dziękuję.","why":"Odwzajemniasz podziękowanie: *Vielen Dank auch Ihnen.*","source":"hueber"}]},{"no":"15","tag":"B3","instruction":"Das kann ich! Ergänzen Sie Informationen über sich.","instruction_en":"Potrafię to! Uzupełnij zdania informacjami o sobie. Przykładowe odpowiedzi to jedna z możliwości.","items":[{"label":"a","lead":"Ich habe schon während der Schulzeit/des Studiums …","text":"","open":true,"solution":"Ich habe schon während der Schulzeit in einem Café gejobbt.","en":"Już w czasie szkoły dorabiałem w kawiarni.","why":"*während* + dopełniacz; czas przeszły Perfekt z imiesłowem na końcu.","source":"g299310"},{"label":"b","lead":"Ich bin/war zuständig für …","text":"","open":true,"solution":"Ich war zuständig für die Buchhaltung in einem kleinen Büro.","en":"Odpowiadałem za księgowość w małym biurze.","why":"*zuständig für* + biernik.","source":"hueber"},{"label":"c","lead":"Ich beherrsche …","text":"","open":true,"solution":"Ich beherrsche Excel und die üblichen Office-Programme.","en":"Biegle obsługuję Excela i popularne programy biurowe.","why":"*beherrschen* + biernik = opanować umiejętność lub język.","source":"hueber"},{"label":"d","lead":"Ich habe auch (sehr) gute Kenntnisse in …","text":"","open":true,"solution":"Ich habe auch sehr gute Kenntnisse in Englisch und Italienisch.","en":"Mam też bardzo dobrą znajomość angielskiego i włoskiego.","why":"*Kenntnisse in* + celownik.","source":"hueber"},{"label":"e","lead":"Es fällt mir leicht, …","text":"","open":true,"solution":"Es fällt mir leicht, im Team zu arbeiten und auf neue Kunden zuzugehen.","en":"Łatwo przychodzi mi praca w zespole i nawiązywanie kontaktu z nowymi klientami.","why":"*Es fällt mir leicht* + *zu* + bezokolicznik; *zugehen* jest rozdzielnie złożony: *zu**zu**gehen*.","source":"g4069"}]}]},{"page":"AB 146","heading":"C  Berufsberatung","heading_en":"Doradztwo zawodowe","exercises":[{"no":"16","tag":"C2","instruction":"Was ist richtig? Lesen Sie und kreuzen Sie an.","instruction_en":"Co jest prawdą? Przeczytaj teksty. Po każdym zdaniu wpisz *richtig* (prawda) lub *falsch* (fałsz); w książce zaznaczasz tylko prawdziwe.","reading":[{"label":"Was wollt ihr werden? – Jacqueline","text":"Ich gehe noch zur Schule. Nächstes Jahr mache ich die Matura. Ein Studium ist aber nichts für mich. Das dauert zu lange. Planung und Organisation sind kein Problem für mich. Deshalb möchte ich einen kaufmännischen Beruf ergreifen. Kommenden Montag habe ich einen Termin bei der Berufsberatung."},{"label":"Konstantinos","text":"In der Schule war ich gut in Mathematik und Kunst. Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte. Und ich wollte auch künstlerisch tätig sein. Aber ich wusste nicht, wie ich das zusammenbringen sollte. Deshalb bin ich zur Berufsberatung gegangen. Der Berater hat mir eine Lehre als Zeichner Landschaftsarchitektur empfohlen. Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt."}],"items":[{"label":"a","text":"Jacqueline hat keine Lust zu studieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Jacqueline hat keine Lust zu studieren. → **richtig**","en":"Jacqueline nie ma ochoty studiować. → prawda","why":"*Ein Studium ist aber nichts für mich. Das dauert zu lange.*","source":"hueber"},{"label":"b","text":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → ___","gaps":[["falsch","f","nein"]],"solution":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → **falsch**","en":"Uważa, że trudno jest coś zaplanować lub zorganizować. → fałsz","why":"Jest odwrotnie: *Planung und Organisation sind kein Problem für mich.*","source":"hueber"},{"label":"c","text":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → **richtig**","en":"W przyszłym tygodniu chce się dowiedzieć czegoś o nauce zawodów handlowo-biurowych. → prawda","why":"*Kommenden Montag habe ich einen Termin bei der Berufsberatung*, w sprawie zawodu handlowo-biurowego.","source":"hueber"},{"label":"d","text":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → ___","gaps":[["richtig","r","ja"]],"solution":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → **richtig**","en":"Konstantinos planował po szkole pracować w dziedzinie techniki. → prawda","why":"*Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte.*","source":"hueber"},{"label":"e","text":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → ___","gaps":[["richtig","r","ja"]],"solution":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → **richtig**","en":"Na początku trudno mu było połączyć swoje zainteresowania. → prawda","why":"*Aber ich wusste nicht, wie ich das zusammenbringen sollte.*","source":"hueber"},{"label":"f","text":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → ___","gaps":[["falsch","f","nein"]],"solution":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → **falsch**","en":"Spodziewał się, że nauka zawodu kreślarza architektury krajobrazu będzie mu sprawiać radość. → fałsz","why":"*Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt* = nie spodziewał się tego.","source":"hueber"}]},{"no":"17","tag":"C2","instruction":"Schreiben Sie Sätze (a–e). Ordnen Sie dann den passenden Ratschlag (1–5) zu.","instruction_en":"Do każdego hasła (a–e) napisz zdanie z *zu* + bezokolicznik. Potem znajdź pasującą radę (1–5); rozwiązanie podaje jej numer.","phrases":["1 Du könntest Busfahrer werden.","2 Dann werde doch Schreiner.","3 Hm, schwierig. Vielleicht Modedesigner?","4 Wie wäre es mit einer Tätigkeit als Bäcker?","5 An deiner Stelle würde ich Köchin werden."],"example":[{"label":"a","lead":"sich gut vorstellen können – im handwerklichen Bereich arbeiten","text":"**Ich kann mir gut vorstellen, im handwerklichen Bereich zu arbeiten.** → 2"}],"items":[{"label":"b","lead":"es nicht schwer finden – früh aufstehen","text":"","accept":["Ich finde es nicht schwer, früh aufzustehen.","Es fällt mir nicht schwer, früh aufzustehen."],"solution":"**Ich finde es nicht schwer, früh aufzustehen.** → 4","en":"Nie uważam, żeby wczesne wstawanie było trudne. → 4 A może praca piekarza?","why":"*Ich finde es* + przymiotnik + *zu* + bezokolicznik; *aufstehen* jest rozdzielnie złożony: *auf**zu**stehen*. Piekarze zaczynają pracę bardzo wcześnie.","source":"g4069","check":"Oficjalny klucz podaje *Es fällt mir nicht schwer, früh aufzustehen*, co znaczy to samo; polecenie *es nicht schwer finden* daje *Ich finde es nicht schwer, …*. Oba zdania są poprawne."},{"label":"c","lead":"Lust haben – viel unterwegs sein","text":"","accept":["Ich habe Lust, viel unterwegs zu sein."],"solution":"**Ich habe Lust, viel unterwegs zu sein.** → 1","en":"Mam ochotę często być w drodze. → 1 Mógłbyś zostać kierowcą autobusu.","why":"*Lust haben* + *zu* + bezokolicznik.","source":"g6865"},{"label":"d","lead":"Freude machen – für andere kochen","text":"","accept":["Es macht mir Freude, für andere zu kochen.","Mir macht es Freude, für andere zu kochen."],"solution":"**Es macht mir Freude, für andere zu kochen.** → 5","en":"Gotowanie dla innych sprawia mi radość. → 5 Na twoim miejscu zostałbym kucharzem.","why":"*Es macht mir Freude* + *zu* + bezokolicznik.","source":"g6865"},{"label":"e","lead":"Interesse haben – Neues entwickeln","text":"","accept":["Ich habe Interesse daran, Neues zu entwickeln.","Ich habe Interesse, Neues zu entwickeln."],"solution":"**Ich habe Interesse daran, Neues zu entwickeln.** → 3","en":"Interesuje mnie tworzenie nowych rzeczy. → 3 Hmm, trudne. Może projektant mody?","why":"*Interesse haben (daran)* + *zu* + bezokolicznik; *daran* zapowiada grupę z *zu*.","source":"g6865"}]},{"no":"18","tag":"C2","instruction":"Wörter mit -ng","instruction_en":"Słowa z -ng","part":"a","part_instruction":"Bilden Sie Wörter mit *-ung*.","part_instruction_en":"Utwórz od czasowników rzeczowniki zakończone na *-ung*, z rodzajnikiem. (Części b–d to zadania ze słuchania i zostały pominięte.)","example":[{"label":"1","text":"beraten → **die Beratung**"},{"label":"4","text":"entwickeln → **die Entwicklung**"}],"items":[{"label":"2","text":"erfahren → ___","gaps":[["die Erfahrung","Erfahrung"]],"solution":"erfahren → **die Erfahrung**","en":"doświadczać → doświadczenie","why":"Temat czasownika + *-ung*; rzeczowniki na *-ung* są zawsze rodzaju żeńskiego: *die*.","source":"hueber"},{"label":"3","text":"verantworten → ___","gaps":[["die Verantwortung","Verantwortung"]],"solution":"verantworten → **die Verantwortung**","en":"odpowiadać za → odpowiedzialność","why":"Temat *verantwort-* + *-ung*: *die Verantwortung*.","source":"hueber"},{"label":"5","text":"beschäftigen → ___","gaps":[["die Beschäftigung","Beschäftigung"]],"solution":"beschäftigen → **die Beschäftigung**","en":"zatrudniać / zajmować → zatrudnienie, zajęcie","why":"Temat *beschäftig-* + *-ung*.","source":"hueber"},{"label":"6","text":"unterstützen → ___","gaps":[["die Unterstützung","Unterstützung"]],"solution":"unterstützen → **die Unterstützung**","en":"wspierać → wsparcie","why":"Temat *unterstütz-* + *-ung*.","source":"hueber"}]}]},{"page":"AB 147","heading":"D  Small Talk: Von der Arbeit erzählen","heading_en":"Small talk: rozmowa o pracy","exercises":[{"no":"19","tag":"D2","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij rozmowę towarzyską między Bettiną (○) a jej znajomym (◆) zwrotami z dwóch ramek (pokazanych tu jako jedna). Każdy zwrot jest użyty raz; przekreślony jest użyty w przykładzie.","box":["es ist total stressig","Hast du noch nie daran gedacht","muss zwei Kollegen vertreten","Hast du immer noch so viel Arbeit","schon mehrere Bewerbungen geschrieben","suche immer noch eine Stelle","Wie läuft's denn so","Ist das nicht anstrengend","machst du jetzt eigentlich genau","habe kein Interesse","komme gut mit den Kunden und den Kollegen zurecht","muss jetzt leider gehen"],"box_used":[6],"box_exact":true,"example":[{"label":"a","text":"◆ Hoi, Bettina. Das ist aber schön, dich zu sehen. **Wie läuft's denn so** mit der Jobsuche?"}],"items":[{"label":"b","text":"○ Schwierig. Ich ___ als Übersetzerin.","gaps":[["suche immer noch eine Stelle"]],"solution":"○ Schwierig. Ich **suche immer noch eine Stelle** als Übersetzerin.","en":"○ Trudno. Wciąż szukam pracy jako tłumaczka.","why":"Po *Ich* stoi czasownik *suche*.","source":"hueber"},{"label":"c","text":"○ Ich habe ___, aber nur Absagen erhalten.","gaps":[["schon mehrere Bewerbungen geschrieben"]],"solution":"○ Ich habe **schon mehrere Bewerbungen geschrieben**, aber nur Absagen erhalten.","en":"○ Napisałam już kilka podań, ale dostałam same odmowy.","why":"Czas przeszły Perfekt: *habe … geschrieben*, pasuje do *erhalten*.","source":"hueber"},{"label":"d","text":"◆ ___, dich selbstständig zu machen? Das machen doch viele Übersetzer.","gaps":[["Hast du noch nie daran gedacht"]],"solution":"◆ **Hast du noch nie daran gedacht**, dich selbstständig zu machen? Das machen doch viele Übersetzer.","en":"◆ Nigdy nie myślałaś o tym, żeby założyć własną działalność? Przecież wielu tłumaczy tak robi.","why":"*daran denken* + *zu* + bezokolicznik; *daran* zapowiada grupę z *zu*.","source":"hueber"},{"label":"e","text":"○ Ja, das stimmt. Aber ___, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","gaps":[["es ist total stressig"]],"solution":"○ Ja, das stimmt. Aber **es ist total stressig**, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","en":"○ Tak, to prawda. Ale ciągłe szukanie zleceń jest strasznie stresujące. Poza tym jest duża konkurencja.","why":"*Es ist* + przymiotnik + *zu* + bezokolicznik.","source":"hueber"},{"label":"f","text":"○ Aber wie geht es dir denn? ___?","gaps":[["Hast du immer noch so viel Arbeit"]],"solution":"○ Aber wie geht es dir denn? **Hast du immer noch so viel Arbeit**?","en":"○ Ale co u ciebie? Wciąż masz tyle pracy?","why":"Odpowiedź *Ja, leider* wymaga pytania tak/nie.","source":"hueber"},{"label":"g","text":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich ___. Und das jetzt, wo wir so viele Aufträge haben!","gaps":[["muss zwei Kollegen vertreten"]],"solution":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich **muss zwei Kollegen vertreten**. Und das jetzt, wo wir so viele Aufträge haben!","en":"◆ Tak, niestety. W naszej firmie kilka osób jest teraz na zwolnieniu. Muszę zastępować dwóch kolegów. I to akurat teraz, kiedy mamy tyle zleceń!","why":"*vertreten* = zastępować kogoś.","source":"hueber"},{"label":"h","text":"○ Was ___?","gaps":[["machst du jetzt eigentlich genau"]],"solution":"○ Was **machst du jetzt eigentlich genau**?","en":"○ A czym ty się właściwie teraz dokładnie zajmujesz?","why":"Pytanie ze słowem pytającym na W (W-Frage): *Was* + czasownik *machst* + *du*.","source":"hueber"},{"label":"i","lead":"◆ Ich bin als Heizungsinstallateur tätig. Ich habe die Verantwortung für zwei Baustellen und soll nebenbei die Baustellen meiner Kollegen betreuen.","text":"○ ___, immer von Baustelle zu Baustelle zu fahren?","gaps":[["Ist das nicht anstrengend"]],"solution":"○ **Ist das nicht anstrengend**, immer von Baustelle zu Baustelle zu fahren?","en":"○ Czy to nie jest męczące, ciągle jeździć z budowy na budowę?","why":"*Ist das nicht anstrengend, … zu* + bezokolicznik?","source":"hueber"},{"label":"j","text":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich ___. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","gaps":[["komme gut mit den Kunden und den Kollegen zurecht"]],"solution":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich **komme gut mit den Kunden und den Kollegen zurecht**. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","en":"◆ Czasem tak, ale przeważnie praca sprawia mi radość. Dobrze dogaduję się z klientami i z kolegami. À propos, moja firma szuka właśnie kogoś do biura. Nie chcesz złożyć podania?","why":"*mit jemandem gut zurechtkommen* = dobrze dogadywać się z kimś (czasownik rozdzielnie złożony).","source":"hueber"},{"label":"k","text":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich ___ an einer Tätigkeit als Sekretärin.","gaps":[["habe kein Interesse"]],"solution":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich **habe kein Interesse** an einer Tätigkeit als Sekretärin.","en":"○ No co ty! Jestem tłumaczką. Nie interesuje mnie praca sekretarki.","why":"*Interesse an* + celownik (*an einer Tätigkeit*).","source":"hueber"},{"label":"l","lead":"◆ Warum nicht? Als Übersetzerin sitzt du doch auch am Computer, schreibst und telefonierst. Der Job ist sicher und unsere Firma zahlt nicht schlecht. Überleg es dir doch einmal.","text":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich ___.","gaps":[["muss jetzt leider gehen"]],"solution":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich **muss jetzt leider gehen**.","en":"○ Dobrze, zrobię tak. Dzięki za radę. Och, niestety muszę już iść.","why":"Typowy sposób na zakończenie small talku.","source":"hueber"}]},{"no":"20","tag":"D2","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij krótkie ogłoszenia. Książka podaje kilka liter każdego słowa; wpisz całe słowo.","example":[{"label":"Beispiel","text":"In den Semesterferien **jobben** – …"}],"items":[{"label":"A","lead":"Ü _ _ _ s _ tz _ _ /in","text":"In den Semesterferien jobben – wir suchen dich als ___/in von kurzen Werbetexten.","gaps":[["Übersetzer"]],"solution":"In den Semesterferien jobben – wir suchen dich als **Übersetzer**/in von kurzen Werbetexten.","en":"Praca dorywcza w przerwie semestralnej – szukamy cię jako tłumacza / tłumaczki krótkich tekstów reklamowych.","why":"*der Übersetzer / die Übersetzerin* = tłumacz / tłumaczka.","source":"hueber"},{"label":"B","lead":"A _ f _ _ ä _ _ n","text":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach ___ suchen.","gaps":[["Aufträgen"]],"solution":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach **Aufträgen** suchen.","en":"Praca na własny rachunek jako pomoc do sprzątania: na Putzfee.net może Pan / Pani zaoferować swoje usługi i szukać zleceń.","why":"*der Auftrag, die Aufträge* = zlecenie, zlecenia; *nach* + celownik liczby mnogiej dodaje *-n*: *Aufträgen*.","source":"hueber"},{"label":"C1","lead":"F _ _ _ b _ _ _ _ g","text":"Machen Sie eine ___. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","gaps":[["Fortbildung"]],"solution":"Machen Sie eine **Fortbildung**. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","en":"Proszę zrobić kurs doszkalający. Oferujemy ciekawe seminaria z zakresu techniki i handlu.","why":"*eine Fortbildung machen* = dokształcać się, zrobić kurs doszkalający.","source":"hueber"},{"label":"C2","lead":"K _ _ k _ _ _ e _ z","text":"Denn die ___ schläft nicht!","gaps":[["Konkurrenz"]],"solution":"Denn die **Konkurrenz** schläft nicht!","en":"Bo konkurencja nie śpi!","why":"*die Konkurrenz* = konkurencja (rywale).","source":"hueber"},{"label":"D","lead":"v _ _ tr _ _ _ n","text":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter ___ können.","gaps":[["vertreten"]],"solution":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter **vertreten** können.","en":"Elastyczni i zmotywowani? Szukamy osób, które mogą na godziny zastępować naszych pracowników magazynu.","why":"Czasownik modalny *können* + bezokolicznik *vertreten* (bez *zu*).","source":"hueber"}]}]},{"page":"AB 148","heading":"Test Lektion 5","heading_en":"Test z lekcji 5","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij zdania. Książka podaje kilka liter każdego słowa; wpisz całe słowo.","example":[{"label":"d","text":"Frau Angst will bald **aufhören** zu arbeiten und in Pension gehen."}],"items":[{"label":"a","lead":"A _ _ t _ ä _ e","text":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele ___.","gaps":[["Aufträge"]],"solution":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele **Aufträge**.","en":"Firma Müller & Müller jest bardzo dobra i dlatego ma dużo zleceń.","why":"*der Auftrag, die Aufträge* = zlecenie, zlecenia; *viele* wymaga liczby mnogiej."},{"label":"b","lead":"V _ r _ n _ w _ _ t _ _ g","text":"Frau Brügger hat die ___ für 200 Mitarbeiter.","gaps":[["Verantwortung"]],"solution":"Frau Brügger hat die **Verantwortung** für 200 Mitarbeiter.","en":"Pani Brügger odpowiada za 200 pracowników.","why":"*die Verantwortung für* + biernik = odpowiedzialność za coś."},{"label":"c","lead":"_ t _ _ _ _ … h _ _","text":"Die Firma ___ die Möbel aus Schweizer Holz ___.","gaps":[["stellt"],["her"]],"solution":"Die Firma **stellt** die Möbel aus Schweizer Holz **her**.","en":"Firma produkuje meble ze szwajcarskiego drewna.","why":"*herstellen* = produkować, wytwarzać; rozdzielnie złożony: *stellt … her*."},{"label":"e","lead":"S _ _ v _ _ _ a _ g _ _ _ _ _ _ _ _ r","text":"Mario ist als ___ in einem Restaurant tätig.","gaps":[["Serviceangestellter"]],"solution":"Mario ist als **Serviceangestellter** in einem Restaurant tätig.","en":"Mario pracuje jako kelner w restauracji.","why":"*der Serviceangestellte* = kelner (użycie szwajcarskie); po *als* bez rodzajnika końcówka to *-er*: *als Serviceangestellter*."},{"label":"f","lead":"z _ st _ _ _ _ g","text":"Peter ist ___ für die Kontrolle und Reparatur der Werkzeugmaschinen.","gaps":[["zuständig"]],"solution":"Peter ist **zuständig** für die Kontrolle und Reparatur der Werkzeugmaschinen.","en":"Peter odpowiada za kontrolę i naprawę obrabiarek.","why":"*zuständig sein für* = odpowiadać za coś."},{"label":"g","lead":"F _ _ _ b _ _ d _ _ g _ n","text":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele ___ an.","gaps":[["Fortbildungen"]],"solution":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele **Fortbildungen** an.","en":"Firma Müller & Müller oferuje swoim pracownikom wiele szkoleń.","why":"*die Fortbildung, die Fortbildungen*; *viele* wymaga liczby mnogiej."}]},{"no":"2","instruction":"Schreiben Sie die Sätze neu.","instruction_en":"Przepisz każde zdanie, zaczynając od podanego początku i używając *zu* + bezokolicznik. Wpisz tylko część po przecinku.","example":[{"label":"a","lead":"Fortbildungen interessieren mich nicht!","text":"Ich habe kein Interesse, **Fortbildungen zu machen**."}],"items":[{"label":"b","lead":"Die Zusammenarbeit mit meinen Kollegen macht mir Freude.","text":"Es macht mir Freude, ___.","gaps":[["mit meinen Kollegen zusammenzuarbeiten"]],"solution":"Es macht mir Freude, **mit meinen Kollegen zusammenzuarbeiten**.","en":"Współpraca z kolegami sprawia mi radość.","why":"*die Zusammenarbeit* → czasownik *zusammenarbeiten*, rozdzielnie złożony: *zusammen**zu**arbeiten*.","source":"g4069"},{"label":"c","lead":"Ich könnte mir eine Arbeit als Pflegefachmann gut vorstellen.","text":"Ich könnte mir gut vorstellen, ___.","gaps":[["als Pflegefachmann zu arbeiten"]],"solution":"Ich könnte mir gut vorstellen, **als Pflegefachmann zu arbeiten**.","en":"Mógłbym sobie dobrze wyobrazić pracę jako pielęgniarz.","why":"*eine Arbeit als …* → *als … zu arbeiten*.","source":"g6865"},{"label":"d","lead":"Der Berufsberater verspricht Hilfe bei der Berufswahl.","text":"Der Berufsberater verspricht, ___.","gaps":[["bei der Berufswahl zu helfen","mir bei der Berufswahl zu helfen","uns bei der Berufswahl zu helfen","bei der Berufswahl zu unterstützen"]],"solution":"Der Berufsberater verspricht, **bei der Berufswahl zu helfen**.","en":"Doradca zawodowy obiecuje pomóc w wyborze zawodu.","why":"*die Hilfe* → czasownik *helfen*: *zu helfen* na końcu.","source":"g6865"}]},{"no":"3","instruction":"Ergänzen Sie: *während – innerhalb – ausserhalb* und *der – ein – …* in der richtigen Form.","instruction_en":"Uzupełnij słowem *während*, *innerhalb* lub *ausserhalb* oraz rodzajnikiem we właściwej formie (dopełniacz). Książka podaje pierwszą literę rodzajnika.","example":[{"label":"a","text":"Sehr geehrter Herr Safak, vielen Dank für Ihre Bewerbung. Wir melden uns **innerhalb der** nächsten Tage bei Ihnen."}],"items":[{"label":"b1","lead":"Sehr geehrter Herr Safak, wir laden Sie zu einem Vorstellungsgespräch am 2.8. um 10 Uhr ein.","text":"___ Gesprächs können Sie natürlich gern Fragen stellen.","gaps":[["Während des"]],"solution":"**Während des** Gesprächs können Sie natürlich gern Fragen stellen.","en":"W trakcie rozmowy może Pan oczywiście śmiało zadawać pytania.","why":"*während* + dopełniacz rodzaju nijakiego: *des Gesprächs*.","source":"g299310"},{"label":"b2","text":"Bitte geben Sie ___ Woche Bescheid, ob Sie kommen.","gaps":[["innerhalb einer"]],"solution":"Bitte geben Sie **innerhalb einer** Woche Bescheid, ob Sie kommen.","en":"Proszę dać znać w ciągu tygodnia, czy Pan przyjdzie.","why":"*innerhalb* + dopełniacz rodzaju żeńskiego: *einer Woche*.","source":"prep"},{"label":"b3","text":"Sie erreichen mich per Telefon oder ___ Bürozeiten per E-Mail.","gaps":[["ausserhalb der"]],"solution":"Sie erreichen mich per Telefon oder **ausserhalb der** Bürozeiten per E-Mail.","en":"Może się Pan ze mną skontaktować telefonicznie albo, poza godzinami pracy biura, mailowo.","why":"*ausserhalb* + dopełniacz liczby mnogiej: *der Bürozeiten*.","source":"prep"}]},{"no":"4","instruction":"Verbinden Sie.","instruction_en":"Dopasuj każde pytanie do odpowiedzi (1–5). Wpisz numer.","phrases":["1 Nein, das kann ich mir nicht vorstellen.","2 Nein, das finde ich nicht.","3 Ja, ich muss eine Kollegin vertreten.","4 Ich beende gerade meine Lehre als Maler.","5 Danke, recht gut. Wir haben viel Arbeit."],"example":[{"label":"a","text":"Wie läuft's denn so in der Firma? → **5** Danke, recht gut. Wir haben viel Arbeit."}],"items":[{"label":"b","text":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → ___","gaps":[["1"]],"solution":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → **1**","en":"Nigdy nie myślałeś o tym, żeby zmienić pracę? → 1 Nie, nie wyobrażam sobie tego.","why":"Pytanie o pomysł: *Nein, das kann ich mir nicht vorstellen.*"},{"label":"c","text":"Was machst du jetzt eigentlich genau? → ___","gaps":[["4"]],"solution":"Was machst du jetzt eigentlich genau? → **4**","en":"Czym ty się właściwie teraz zajmujesz? → 4 Właśnie kończę naukę zawodu malarza.","why":"Pytanie ze słowem pytającym na W o twoją pracę wymaga odpowiedzi z konkretnym faktem."},{"label":"d","text":"Ist es nicht stressig, nachts zu arbeiten? → ___","gaps":[["2"]],"solution":"Ist es nicht stressig, nachts zu arbeiten? → **2**","en":"Czy praca w nocy nie jest stresująca? → 2 Nie, nie uważam tak.","why":"*Ist es nicht stressig …?* pyta o opinię: *Nein, das finde ich nicht.*"},{"label":"e","text":"Hast du immer noch so viel Arbeit? → ___","gaps":[["3"]],"solution":"Hast du immer noch so viel Arbeit? → **3**","en":"Wciąż masz tyle pracy? → 3 Tak, muszę zastępować koleżankę.","why":"Pytanie tak/nie; powód, dla którego jest tyle pracy: *eine Kollegin vertreten*."}]}]},{"page":"AB 149","heading":"Fokus Beruf: Etwas verhandeln","heading_en":"Praca w centrum uwagi: negocjacje","exercises":[{"no":"1","instruction":"Vier gute Tipps","instruction_en":"Cztery dobre wskazówki","part":"a","part_instruction":"Wofür bekommt man hier Tipps? Überfliegen Sie den Text und kreuzen Sie an.","part_instruction_en":"Do czego służą te wskazówki? Przejrzyj tekst i wpisz właściwą odpowiedź. (Ćwiczenia 2 i 3 na tej stronie to zadania ze słuchania i zostały pominięte.)","reading":[{"label":"So kommen Sie weiter!","text":"Ist das Bewerbungsgespräch gut gelaufen? Herzlichen Glückwunsch! Jetzt haben Sie es fast geschafft. Aber wenn es im Bewerbungsgespräch zum Thema Geld kommt, machen viele Bewerber Fehler: Sie fordern zu viel Lohn – oder zu wenig. Unsere Tipps helfen Ihnen bei diesem schwierigen Thema.\n1  Sprechen Sie das Thema Geld nicht selbst an. Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.\n2  Nennen Sie Ihre Gehaltsvorstellung. Wenn Sie vorher in anderen Unternehmen gearbeitet haben, ist Ihr letztes Gehalt die Grundlage.\n3  Natürlich können Sie an einem neuen Arbeitsplatz mehr Lohn verlangen, aber bleiben Sie realistisch und begründen Sie Ihre Gehaltsvorstellung: Haben Sie mehr Verantwortung? Können Sie mit besonderen Kenntnissen, Fähigkeiten oder Erfahrungen punkten? War der alte Arbeitgeber besonders zufrieden mit Ihnen?\n4  Was ist, wenn die Personalchefin oder der Personalchef negativ auf Ihre Gehaltsvorstellung reagiert? Dann müssen Sie flexibel sein und andere Vorschläge machen. Erklären Sie zum Beispiel, dass Sie mit weniger Lohn einverstanden sind, wenn die Firma Ihnen eine Weiter- oder Fortbildung bezahlt. Oder wenn Sie nach sechs Monaten mehr Lohn bekommen."}],"items":[{"label":"1","lead":"○ Für Gespräche mit der Bank   ○ Für Gespräche mit dem Arbeitgeber","text":"___","gaps":[["Für Gespräche mit dem Arbeitgeber","mit dem Arbeitgeber","Arbeitgeber","dem Arbeitgeber"]],"solution":"**Für Gespräche mit dem Arbeitgeber**","en":"Do rozmów z pracodawcą","why":"Wskazówki dotyczą rozmowy o pieniądzach na rozmowie kwalifikacyjnej, z szefową lub szefem działu personalnego.","source":"hueber"}]},{"no":"1","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Co jest prawdą? Przeczytaj jeszcze raz. Po każdym zdaniu wpisz *richtig* (prawda) lub *falsch* (fałsz); w książce zaznaczasz tylko prawdziwe.","items":[{"label":"1","text":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → ___","gaps":[["richtig","r","ja"]],"solution":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → **richtig**","en":"Poruszenie tematu wynagrodzenia to zadanie szefowej / szefa działu personalnego. → prawda","why":"Wskazówka 1: *Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.*","source":"hueber"},{"label":"2","text":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → ___","gaps":[["falsch","f","nein"]],"solution":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → **falsch**","en":"W nowym miejscu pracy dostaje Pan / Pani na początku takie samo wynagrodzenie jak w starej firmie. → fałsz","why":"Wskazówki 2 i 3: twoje ostatnie wynagrodzenie to tylko punkt wyjścia; możesz poprosić o więcej.","source":"hueber"},{"label":"3","text":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → ___","gaps":[["richtig","r","ja"]],"solution":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → **richtig**","en":"Jeśli chce Pan / Pani zarabiać więcej, warto podać na to dobre argumenty. → prawda","why":"Wskazówka 3: *begründen Sie Ihre Gehaltsvorstellung*.","source":"hueber"},{"label":"4","text":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → ___","gaps":[["falsch","f","nein"]],"solution":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → **falsch**","en":"Jeśli szefowa / szef działu personalnego nie zgadza się z Pana / Pani propozycją, nic więcej nie da się zrobić. → fałsz","why":"Wskazówka 4: bądź elastyczny i zaproponuj coś innego (opłacone szkolenie, wyższe wynagrodzenie po sześciu miesiącach).","source":"hueber"}]}]}]}];
